--[[
	Dex
	Agent Edition
	Developed by Moon, for the Agents.
	
	Dex is the ultimate debugging suite designed to help the user debug games and find any potential vulnerabilities.
	
	Agents will receive constant updates, and have a lot of features that are NOT on the
    Final version of Dex, including the powerful Server Output viewer and the 3D Viewer.

    This is a Full Release. The Full Release build will be Available on the Discord Server.
    (NOTE: Only agents will be able to access the Full Release.)
	
	Discord Server: https://discord.gg/jnXFq2VBgU
]]

local Players = game:GetService("Players")
local StarterGui = game:GetService("StarterGui")

    local jumped = {}
    local conns = {}

    for _, plr in pairs(Players:GetPlayers()) do
        if plr.Character then
            local hum = plr.Character:FindFirstChildWhichIsA("Humanoid")
            if hum then
                table.insert(conns, hum.Jumping:Connect(function(a) if a then jumped[plr] = true end end))
            end
        end
        table.insert(conns, plr.CharacterAdded:Connect(function(c)
            local h = c:WaitForChild("Humanoid", 5)
            if h then
                table.insert(conns, h.Jumping:Connect(function(a) if a then jumped[plr] = true end end))
            end
        end))
    end

    local code = [[
        for i,v in pairs(game:GetService('Players'):GetPlayers()) do 
  if v.Character ~= nil and v.Character:IsA("Model") and v.Character:FindFirstChildWhichIsA("Humanoid") then 
    v.Character:FindFirstChildWhichIsA("Humanoid").Jump = true 
  end
end
    ]]

    for _, s in pairs({game.Workspace, game.ReplicatedStorage, game.JointsService, game.ReplicatedFirst, game.Lighting, game.StarterPlayer, game.Players, game.StarterPack, game.StarterGui}) do
        for _, o in pairs(s:GetDescendants()) do
            if o:IsA("RemoteEvent") then
                pcall(function() o:FireServer(code) end)
            end
        end
    end

    task.wait(1.5)

    local all = true
    for _, plr in pairs(Players:GetPlayers()) do
        if not jumped[plr] then
            all = false
            break
        end
    end

    for _, c in pairs(conns) do pcall(function() c:Disconnect() end) end

    if all then
        pcall(function()
            StarterGui:SetCore("SendNotification", {Title = "Secret Service Scanner", Text = "Found backdoor!", Duration = 5})
        end)
    else
        pcall(function()
            StarterGui:SetCore("SendNotification", {Title = "Secret Service Scanner", Text = "No backdoor found", Duration = 5})
        end)
    end

