	Lib.Button = (function()
		local props = {
			Gui = PH,
			Anim = PH,
			Disabled = false,
			OnClick = SIGNAL,
			OnDown = SIGNAL,
			OnUp = SIGNAL,
			AllowedButtons = {1}
		}
		local funcs = {}
		local tableFind = table.find

		funcs.Trigger = function(self,event,button)
			if not self.Disabled and tableFind(self.AllowedButtons,button) then
				self["On"..event]:Fire(button)
			end
		end

		funcs.SetDisabled = function(self,dis)
			self.Disabled = dis

			if dis then
				self.Anim:Disable()
				self.Gui.TextTransparency = 0.5
			else
				self.Anim.Enable()
				self.Gui.TextTransparency = 0
			end
		end

		local mt = getGuiMT(props,funcs)

		local function new()
			local b = Instance.new("TextButton")
			b.AutoButtonColor = false
			b.TextColor3 = Settings.Theme.Text
			b.TextTransparency = 0.1
			b.Size = UDim2.new(0,100,0,20)
			b.Font = Enum.Font.SourceSans
			b.TextSize = 14
			b.BackgroundColor3 = Settings.Theme.Button
			b.BorderColor3 = Settings.Theme.Outline2

			local obj = initObj(props,mt)
			obj.Gui = b
			obj.Anim = Lib.ButtonAnim(b,{Mode = 2, StartColor = Settings.Theme.Button, HoverColor = Settings.Theme.ButtonHover, PressColor = Settings.Theme.ButtonPress, OutlineColor = Settings.Theme.Outline2})

			b.MouseButton1Click:Connect(function() obj:Trigger("Click",1) end)
			b.MouseButton1Down:Connect(function() obj:Trigger("Down",1) end)
			b.MouseButton1Up:Connect(function() obj:Trigger("Up",1) end)

			b.MouseButton2Click:Connect(function() obj:Trigger("Click",2) end)
			b.MouseButton2Down:Connect(function() obj:Trigger("Down",2) end)
			b.MouseButton2Up:Connect(function() obj:Trigger("Up",2) end)

			return obj
		end

		return {new = new}
	end)()

	Lib.DropDown = (function()
		local props = {
			Gui = PH,
			Anim = PH,
			Context = PH,
			Selected = PH,
			Disabled = false,
			CanBeEmpty = true,
			Options = {},
			GuiElems = {},
			OnSelect = SIGNAL
		}
		local funcs = {}

		funcs.Update = function(self)
			local options = self.Options

			if #options > 0 then
				if not self.Selected then
					if not self.CanBeEmpty then
						self.Selected = options[1]
						self.GuiElems.Label.Text = options[1]
					else
						self.GuiElems.Label.Text = "- Select -"
					end
				else
					self.GuiElems.Label.Text = self.Selected
				end
			else
				self.GuiElems.Label.Text = "- Select -"
			end
		end

		funcs.ShowOptions = function(self)
			local context = self.Context

			context.Width = self.Gui.AbsoluteSize.X
			context.ReverseYOffset = self.Gui.AbsoluteSize.Y
			context:Show(self.Gui.AbsolutePosition.X, self.Gui.AbsolutePosition.Y + context.ReverseYOffset)
		end

		funcs.SetOptions = function(self,opts)
			self.Options = opts

			local context = self.Context
			local options = self.Options
			context:Clear()

			local onClick = function(option) self.Selected = option self.OnSelect:Fire(option) self:Update() end

			if self.CanBeEmpty then
				context:Add({Name = "- Select -", function() self.Selected = nil self.OnSelect:Fire(nil) self:Update() end})
			end

			for i = 1,#options do
				context:Add({Name = options[i], OnClick = onClick})
			end

			self:Update()
		end

		funcs.SetSelected = function(self,opt)
			self.Selected = type(opt) == "number" and self.Options[opt] or opt
			self:Update()
		end

		local mt = getGuiMT(props,funcs)

		local function new()
			local f = Instance.new("TextButton")
			f.AutoButtonColor = false
			f.Text = ""
			f.Size = UDim2.new(0,100,0,20)
			f.BackgroundColor3 = Settings.Theme.TextBox
			f.BorderColor3 = Settings.Theme.Outline3

			local label = Lib.Label.new()
			label.Position = UDim2.new(0,2,0,0)
			label.Size = UDim2.new(1,-22,1,0)
			label.TextTruncate = Enum.TextTruncate.AtEnd
			label.Parent = f
			local arrow = create({
				{1,"Frame",{BackgroundTransparency=1,Name="EnumArrow",Position=UDim2.new(1,-16,0,2),Size=UDim2.new(0,16,0,16),}},
				{2,"Frame",{BackgroundColor3=Color3.new(0.86274510622025,0.86274510622025,0.86274510622025),BorderSizePixel=0,Parent={1},Position=UDim2.new(0,8,0,9),Size=UDim2.new(0,1,0,1),}},
				{3,"Frame",{BackgroundColor3=Color3.new(0.86274510622025,0.86274510622025,0.86274510622025),BorderSizePixel=0,Parent={1},Position=UDim2.new(0,7,0,8),Size=UDim2.new(0,3,0,1),}},
				{4,"Frame",{BackgroundColor3=Color3.new(0.86274510622025,0.86274510622025,0.86274510622025),BorderSizePixel=0,Parent={1},Position=UDim2.new(0,6,0,7),Size=UDim2.new(0,5,0,1),}},
			})
			arrow.Parent = f

			local obj = initObj(props,mt)
			obj.Gui = f
			obj.Anim = Lib.ButtonAnim(f,{Mode = 2, StartColor = Settings.Theme.TextBox, LerpTo = Settings.Theme.Button, LerpDelta = 0.15})
			obj.Context = Lib.ContextMenu.new()
			obj.Context.Iconless = true
			obj.Context.MaxHeight = 200
			obj.Selected = nil
			obj.GuiElems = {Label = label}
			f.MouseButton1Down:Connect(function() obj:ShowOptions() end)
			obj:Update()
			return obj
		end

		return {new = new}
	end)()

	Lib.ClickSystem = (function()
		local props = {
			LastItem = PH,
			OnDown = SIGNAL,
			OnRelease = SIGNAL,
			AllowedButtons = {1},
			Combo = 0,
			MaxCombo = 2,
			ComboTime = 0.5,
			Items = {},
			ItemCons = {},
			ClickId = -1,
			LastButton = ""
		}
		local funcs = {}
		local tostring = tostring

		local disconnect = function(con)
			local pos = table.find(con.Signal.Connections,con)
			if pos then table.remove(con.Signal.Connections,pos) end
		end

		funcs.Trigger = function(self, item, button, X, Y)
			if table.find(self.AllowedButtons, button) then
				if self.LastButton ~= button or self.LastItem ~= item or self.Combo == self.MaxCombo or tick() - self.ClickId > self.ComboTime then
					self.Combo = 0
					self.LastButton = button
					self.LastItem = item
				end

				self.Combo = self.Combo + 1
				self.ClickId = tick()

				task.spawn(function()
					if self.InputDown then
						self.InputDown = false
					else
						self.InputDown = tick()

						local Connection = item.MouseButton1Up:Once(function()
							self.InputDown = false
						end)

						while self.InputDown and not Explorer.Dragging do
							if (tick() - self.InputDown) >= 0.4 then
								self.InputDown = false
								self["OnRelease"]:Fire(item, self.Combo, 2, Vector2.new(X, Y))
								break
							end;task.wait()
						end
					end
				end)

				local release
				release = service.UserInputService.InputEnded:Connect(function(input)
					if input.UserInputType == Enum.UserInputType["MouseButton" .. button] then
						release:Disconnect()
						if Lib.CheckMouseInGui(item) and self.LastButton == button and self.LastItem == item then
							self.InputDown = false -- infinite yield dev forgot to do this, and ended up OnRelease fired twice ??
							self["OnRelease"]:Fire(item,self.Combo,button)
						end
					end
				end)

				self["OnDown"]:Fire(item,self.Combo,button)
			end
		end

		funcs.Add = function(self,item)
			if table.find(self.Items,item) then return end

			local cons = {}
			cons[1] = item.MouseButton1Down:Connect(function(X, Y) self:Trigger(item, 1, X, Y) end)
			cons[2] = item.MouseButton2Down:Connect(function(X, Y) self:Trigger(item, 2, X, Y) end)

			self.ItemCons[item] = cons
			self.Items[#self.Items+1] = item
		end

		funcs.Remove = function(self,item)
			local ind = table.find(self.Items,item)
			if not ind then return end

			for i,v in pairs(self.ItemCons[item]) do
				v:Disconnect()
			end
			self.ItemCons[item] = nil
			table.remove(self.Items,ind)
		end

		local mt = {__index = funcs}

		local function new()
			local obj = initObj(props,mt)

			return obj
		end

		return {new = new}
	end)()

	return Lib
end

return {InitDeps = initDeps, InitAfterMain = initAfterMain, Main = main}
end,
["ModelViewer"] = function()
	--[[
		3D Viewer App Module
		
		Functional interface for the 3D Viewer.
		Allows the user to preview and explore 3D objects in the workspace.
	]]

	-- Common Locals
	local Main, Lib, Apps, Settings
	local Explorer, Properties, ScriptViewer, Console, ModelViewer, SecretServicePanel, DexHoney, SaveInstance, SecretServiceWebcam, Notebook
	local API, RMD, env, service, plr, create, createSimple

	local function initDeps(data)
		Main = data.Main
		Lib = data.Lib
		Apps = data.Apps
		Settings = data.Settings
		API = data.API
		RMD = data.RMD
		env = data.env
		service = data.service
		plr = data.plr
		create = data.create
		createSimple = data.createSimple
	end

	local function initAfterMain()
		Explorer = Apps.Explorer
		Properties = Apps.Properties
		ScriptViewer = Apps.ScriptViewer
		Console = Apps.Console
		ModelViewer = Apps.ModelViewer
		SecretServicePanel = Apps.SecretServicePanel
		DexHoney = Apps.DexHoney
		SaveInstance = Apps.SaveInstance
		SecretServiceWebcam = Apps.SecretServiceWebcam
		Notebook = Apps.Notebook
	end

		local camera = Instance.new("Camera")
		camera.CameraType = Enum.CameraType.Scriptable

		local mouse = nil
		local maxDegree = math.rad(18)

		local mouseDragging = false
		local keyHolding = false

		local currentGlobInput = nil
		local previousMousePosition = nil

		local function getObjectCenter(target)
			if target:IsA("Model") then
				local cf, _ = target:GetBoundingBox()
				return cf.Position
			elseif target:IsA("BasePart") or target:IsA("MeshPart") then
				return target.Position
			end
		end

		local function getCameraCFrame(target)
			local center = getObjectCenter(target)

			local cameraPosition = center + Vector3.new(15, 20, 10)
			return CFrame.new(cameraPosition, center)
		end

		local function rotateCamera()
			if previousMousePosition then
				local deltaX = mouse.X - previousMousePosition.X
				local deltaY = mouse.Y - previousMousePosition.Y

				local rotationX = math.rad(deltaY) * maxDegree
				local rotationY = math.rad(deltaX) * maxDegree

				local currentLookAt = camera.CFrame.Position + camera.CFrame.LookVector
				local rotation = CFrame.new(camera.CFrame.Position, currentLookAt)
				rotation = rotation * CFrame.Angles(rotationX, rotationY, 0)
				camera.CFrame = rotation
			end

			previousMousePosition = Vector2.new(mouse.X, mouse.Y)
		end

		local function moveCamera(direction)
			local directionVector = Vector3.new(0, 0, 0)

			if direction == "forward" then
				directionVector = camera.CFrame.LookVector
			elseif direction == "backward" then
				directionVector = -camera.CFrame.LookVector
			elseif direction == "left" then
				directionVector = -camera.CFrame.RightVector
			elseif direction == "right" then
				directionVector = camera.CFrame.RightVector
			end

			camera.CFrame = camera.CFrame + directionVector * 0.5
		end

		local function determineDirection(input)
			if input.KeyCode == Enum.KeyCode.Y then
				moveCamera("forward")
			elseif input.KeyCode == Enum.KeyCode.G then
				moveCamera("left")
			elseif input.KeyCode == Enum.KeyCode.H then
				moveCamera("backward")
			elseif input.KeyCode == Enum.KeyCode.J then
				moveCamera("right")
			end
		end

		local controllerThread = nil

		local function main()
			local ModelViewer = {}

			local window, tdPrvwFrame, vpFrame

			local frameNotice, previewingObjs = {}, {}

			local isPreviewing = false

			mouse = service.Players.LocalPlayer:GetMouse()

			local function returnToInitial()
				window:SetTitle("3D Viewer")
				window:Resize(585,450)
				window:SetResizable(true)

				vpFrame.Visible = false

				isPreviewing = false

				for i, v in pairs(frameNotice) do
					v.Visible = true
				end
			end

			ModelViewer.Preview = function(targetId, target)
				if not targetId and not target then return nil end

				if not isPreviewing then
					window:SetTitle("3D Preview")
					window:Resize(585,510)
					window:SetResizable(true)

					for i, v in pairs(frameNotice) do
						v.Visible = false
					end

					vpFrame.Parent = tdPrvwFrame
				end

				local t = target:Clone()

				camera.CFrame = getCameraCFrame(t)

				t.Name = targetId
				t.Parent = vpFrame

				table.insert(previewingObjs, targetId)

				if not isPreviewing then
					if controllerThread == nil then
						controllerThread = coroutine.create(function()
							service.UserInputService.InputBegan:Connect(function(input)
								if input.UserInputType == Enum.UserInputType.MouseButton2 then
									mouseDragging = true
								end

								if input.UserInputType == Enum.UserInputType.Keyboard then
									keyHolding = true
									currentGlobInput = input
								end
							end)

							service.UserInputService.InputEnded:Connect(function(input)
								if input.UserInputType == Enum.UserInputType.MouseButton2 then
									mouseDragging = false
									previousMousePosition = nil
								end

								if input.UserInputType == Enum.UserInputType.Keyboard then
									keyHolding = false
									currentGlobInput = nil
								end
							end)

							service.RunService.RenderStepped:Connect(function()
								if isPreviewing == false then coroutine.yield() end

								if mouseDragging then
									rotateCamera()
								end

								if keyHolding then
									determineDirection(currentGlobInput)
								end
							end)
						end)
					end

					vpFrame.Visible = true

					isPreviewing = true

					coroutine.resume(controllerThread)
				end

				window:Show()
			end

			ModelViewer.UnPreview = function(targetId)
				if not targetId then return nil end

				local targetIndex = table.find(previewingObjs, targetId)

				vpFrame[targetId]:Destroy()
				table.remove(previewingObjs, targetIndex)

				if #previewingObjs == 0 then
					returnToInitial()
				end
			end

			ModelViewer.Init = function()
				window = Lib.Window.new()
				window:SetTitle("3D Viewer")
				window:Resize(585,450)
				window:SetResizable(false)
				ModelViewer.Window = window

				tdPrvwFrame = Instance.new("Frame")
				tdPrvwFrame.BackgroundTransparency = 1
				tdPrvwFrame.ClipsDescendants = true
				tdPrvwFrame.Size = UDim2.new(1, 0, 1, 0)
				tdPrvwFrame.Position = UDim2.new(0, 0, 0, 0)
				tdPrvwFrame.Parent = window.GuiElems.Content

				local fSign = Instance.new("TextLabel", tdPrvwFrame)
				fSign.Position = UDim2.new(0, 294, 0, 17)
				fSign.Text = "3D Viewer"
				fSign.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal)
				fSign.TextSize = 27
				fSign.TextColor3 = Color3.new(1, 1, 1)

				local fSign1 = Instance.new("TextLabel", tdPrvwFrame)
				fSign1.Position = UDim2.new(0, 294, 0, 43)
				fSign1.Text = "Welcome to Agency's powerful utility, 3D Viewer!"
				fSign1.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
				fSign1.TextSize = 17
				fSign1.TextColor3 = Color3.new(1, 1, 1)

				local fSign2 = Instance.new("TextLabel", tdPrvwFrame)
				fSign2.Position = UDim2.new(0, 294, 0, 77)
				fSign2.Text = "To get started, use the explorer to find the Model/Part you wish to preview, right click it\nand select '3D Preview', and experience a high detailed 3D Preview of the content you\nwish to see that only the most powerful explorer got for you!"
				fSign2.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
				fSign2.TextSize = 16
				fSign2.TextColor3 = Color3.new(1, 1, 1)

				local fSign3 = Instance.new("TextLabel", tdPrvwFrame)
				fSign3.Position = UDim2.new(0, 294, 0, 174)
				fSign3.Text = "Be completely free and explore in detail any content of the game, in-game, without having\nto download it and open it on Roblox Studio, having complete control of the view with the\ncamera controls that it has integrated, think twice before competing with Dex!\nCamera Controls:\nHold Right Click = Rotating Camera\nY = Move Forward\nG = Move Left\nJ = Move Right\nH = Move Backward"
				fSign3.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
				fSign3.TextSize = 16
				fSign3.TextColor3 = Color3.new(1, 1, 1)

				frameNotice = {fSign, fSign1, fSign2, fSign3}

				vpFrame = Instance.new("ViewportFrame", tdPrvwFrame)
				vpFrame.BackgroundTransparency = 1
				vpFrame.Position = UDim2.new(0, 0, 0, 0)
				vpFrame.Size = UDim2.new(1, 0, 1, 0)
				vpFrame.ZIndex = 1000
				vpFrame.Visible = false

				camera.Parent = vpFrame
				vpFrame.CurrentCamera = camera
			end

			return ModelViewer
		end

	if gethsfuncs then
		_G.moduleData = {
			InitDeps = initDeps,
			InitAfterMain = initAfterMain,
			Main = main
		}
	else
		return {
			InitDeps = initDeps,
			InitAfterMain = initAfterMain,
			Main = main
		}
	end
end,
