			Properties.DisplayAddAttributeWindow(prop)
		end})
		context:Add({Name = "Delete", OnClick = function()
			Properties.SetProp(prop,nil,true)
			Properties.ShowExplorerProps()
		end})

		context:Show()
	end
	
	local HttpService = game:GetService("HttpService")
	local function getRelativePath(root,obj)
	local path = {}
	local current = obj

	while current and current ~= root do
		table.insert(path,1,current.Name)
		current = current.Parent
	end

	return table.concat(path,"/")
end
	local function compilePlayerData(player)
		local data = {
			Inventory = {},
			Values = {},
		}

		for _, child in ipairs(player:GetDescendants()) do
			if child:IsA("ValueBase") then
				data.Values[getRelativePath(player,child)] = {
					Type = child.ClassName,
					Value = child.Value
				}

			end
		end

		local inventory = player:FindFirstChild("Backpack")
		if inventory then
			for _, item in ipairs(inventory:GetChildren()) do
				table.insert(data.Inventory, item.Name)
			end
		end

		return data
	end
	
	local ValEditorWindnow = false
	
	local function prettyJSON(str)
	local indent = 0

	str = str:gsub("{",function()
		indent += 1
		return "{\n"..string.rep("  ",indent)
	end)

	str = str:gsub("}",function()
		indent -= 1
		return "\n"..string.rep("  ",indent).."}"
	end)

	str = str:gsub(",",",\n"..string.rep("  ",indent))

	return str
end

