		scrollV.Gui.Parent = window.GuiElems.Content
		scrollH.Gui.Parent = window.GuiElems.Content
		Properties.InitInputBox()
		Properties.InitSearch()
	end

	return Properties
end

	if gethsfuncs then
		_G.moduleData = {
			InitDeps = initDeps,
			InitAfterMain = initAfterMain,
			Main = main
		}
	else
		return {
			InitDeps = initDeps,
			InitAfterMain = initAfterMain,
			Main = main
		}
	end
end,
["SaveInstance"] = function()
--[[
	Save Instance App Module
	
	Revival of the old dex's Save Instance
]] 

-- Common Locals
local Main,Lib,Apps,Settings -- Main Containers
local Explorer, Properties, ScriptViewer, SaveInstance, Notebook -- Major Apps
local API,RMD,env,service,plr,create,createSimple -- Main Locals

local function initDeps(data)
	Main = data.Main
	Lib = data.Lib
	Apps = data.Apps
	Settings = data.Settings

	API = data.API
	RMD = data.RMD
	env = data.env
	service = data.service
	plr = data.plr
	create = data.create
	createSimple = data.createSimple
end

local function initAfterMain()
	Explorer = Apps.Explorer
	Properties = Apps.Properties
	ScriptViewer = Apps.ScriptViewer
	SaveInstance = Apps.SaveInstance
	Notebook = Apps.Notebook
end

local function main()
	local SaveInstanceApp = {}
	local window, ListFrame
	local fileName = "Place_"..game.PlaceId.."_"..game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId).Name.."_{TIMESTAMP}"
	local Saving = false
	
	local SaveInstanceArgs = {
		Decompile = true,
		DecompileTimeout = 10,
		DecompileIgnore = {"Chat", "CoreGui", "CorePackages"},
		NilInstances = false,
		RemovePlayerCharacters = true,
		SavePlayers = false,
		MaxThreads = 3,
		ShowStatus = true,
		IgnoreDefaultProps = true,
		IsolateStarterPlayer = true
	}
	
	local function AddCheckbox(title, default)
		local frame = Lib.Frame.new()
		frame.Gui.Parent = ListFrame
		frame.Gui.Transparency = 1
		frame.Gui.Size = UDim2.new(1,0,0,20)
		
		local listlayout = Instance.new("UIListLayout")
		listlayout.Parent = frame.Gui
		listlayout.FillDirection = Enum.FillDirection.Horizontal
		listlayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
		listlayout.VerticalAlignment = Enum.VerticalAlignment.Center
		listlayout.Padding = UDim.new(0, 10)
		
		-- Checkbox
		local checkbox = Lib.Checkbox.new()
		
		checkbox.Gui.Parent = frame.Gui
		checkbox.Gui.Size = UDim2.new(0,15,0,15)
		
		-- Label
		local label = Lib.Label.new()
		
		label.Gui.Parent = frame.Gui
		label.Gui.Size = UDim2.new(1, 0,1, -15)
		label.Gui.Text = title
		label.TextTruncate = Enum.TextTruncate.AtEnd
		
		checkbox:SetState(default)
		
		return checkbox
	end
	
	local function AddTextbox(title, default, sizeX)
		default = tostring(default)
		local frame = Lib.Frame.new()
		frame.Gui.Parent = ListFrame
		frame.Gui.Transparency = 1
		frame.Gui.Size = UDim2.new(1,0,0,20)

		local listlayout = Instance.new("UIListLayout")
		listlayout.Parent = frame.Gui
		listlayout.FillDirection = Enum.FillDirection.Horizontal
		listlayout.HorizontalAlignment = Enum.HorizontalAlignment.Left
		listlayout.VerticalAlignment = Enum.VerticalAlignment.Center
		listlayout.Padding = UDim.new(0, 10)

		-- Textbox
		local textbox = Instance.new("TextBox") -- replaced cuz why Moon make every inputs only work on mouse/pc users >:( 
		textbox.BackgroundColor3 = Settings.Theme.TextBox
		textbox.BorderColor3 = Settings.Theme.Outline3
		textbox.ClearTextOnFocus = false
		textbox.TextColor3 = Settings.Theme.Text
		textbox.Font = Enum.Font.SourceSans
		textbox.TextSize = 14
		textbox.ZIndex = 2

		textbox.Parent = frame.Gui
		if sizeX and type(sizeX) == "number" then
			textbox.Size = UDim2.new(0,sizeX,0,15)
		else
			textbox.Size = UDim2.new(0,45,0,15)
		end
		
		frame.Gui.AutomaticSize = Enum.AutomaticSize.X
		textbox.AutomaticSize = Enum.AutomaticSize.X

		-- Label
		local label = Lib.Label.new()

		label.Parent = frame.Gui
		label.Size = UDim2.new(1, 0,1, -15)
		label.Text = title
		label.TextTruncate = Enum.TextTruncate.AtEnd

		textbox.Text = default

		return {TextBox = textbox}
	end
	
	SaveInstanceApp.Init = function()
		window = Lib.Window.new()
		window:SetTitle("Save Instance")
		window:Resize(350,350)
		SaveInstanceApp.Window = window
		
		-- ListFrame
		
		-- Fake ScrollBar dex, because its too advanced
		ListFrame = Instance.new("ScrollingFrame")
		ListFrame.Parent = window.GuiElems.Content
		ListFrame.Size = UDim2.new(1, 0,1, -40)
		ListFrame.Position = UDim2.new(0, 0, 0, 0)
		ListFrame.Transparency = 1
		ListFrame.CanvasSize = UDim2.new(0,0,0,0)
		ListFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
		ListFrame.ScrollBarThickness = 16
		ListFrame.BottomImage = ""
		ListFrame.TopImage = ""
		ListFrame.ScrollBarImageColor3 = Color3.fromRGB(70, 70, 70)
		ListFrame.ScrollBarImageTransparency = 0
		ListFrame.ZIndex = 2
		ListFrame.BorderSizePixel = 0
		
		local scrollbar = Lib.ScrollBar.new()
		scrollbar.Gui.Parent = window.GuiElems.Content
		scrollbar.Gui.Size = UDim2.new(1, 0,1, -40)
		scrollbar.Gui.Up.ZIndex = 3
		scrollbar.Gui.Down.ZIndex = 3
		
		ListFrame:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(function()
			if ListFrame.AbsoluteCanvasSize ~= ListFrame.AbsoluteWindowSize then
				scrollbar.Gui.Visible = true
			else
				scrollbar.Gui.Visible = false
			end
		end)
		
		local ListLayout = Instance.new("UIListLayout")
		ListLayout.Parent = ListFrame
		ListLayout.Padding = UDim.new(0, 5)
		
		local Padding = Instance.new("UIPadding")
		Padding.Parent = ListFrame
		Padding.PaddingBottom = UDim.new(0, 5)
		Padding.PaddingLeft = UDim.new(0, 10)
		Padding.PaddingRight = UDim.new(0, 10)
		Padding.PaddingTop = UDim.new(0, 5)
		
		-- Options
		
		local Decompile = AddCheckbox("Decompile Scripts (LocalScript and ModuleScript)", SaveInstanceArgs.Decompile)
		Decompile.OnInput:Connect(function()
			SaveInstanceArgs.Decompile = Decompile.Toggled
		end)
		
		local decompileTimeout = AddTextbox("Decompile Timeout (s)", SaveInstanceArgs.DecompileTimeout, 15)
		decompileTimeout.TextBox.FocusLost:Connect(function()
			SaveInstanceArgs.DecompileTimeout = tonumber(decompileTimeout.TextBox.Text)
		end)
		
		local decompileThread = AddTextbox("Decompiler Max Threads", "3", 15)
		decompileThread.TextBox.FocusLost:Connect(function()
			SaveInstanceArgs.MaxThreads = tonumber(decompileThread.TextBox.Text)
		end)
		
		local decompileIgnore = AddTextbox("Decompile Ignore", table.concat(SaveInstanceArgs.DecompileIgnore, ","), 50)
		decompileIgnore.TextBox.FocusLost:Connect(function()
			local inputText = decompileIgnore.TextBox.Text
			local rawList = string.split(inputText, ", ") or string.split(inputText, ",")
			local finalList = {}

			for _, text in ipairs(rawList) do
				local split = string.split(text, ",") or string.split(text, ", ")
				for _, textFound in ipairs(split) do
					table.insert(finalList, textFound)
				end
			end
			SaveInstanceArgs.DecompileIgnore = finalList
		end)

		
		local NilObj = AddCheckbox("Save Nil Instances", SaveInstanceArgs.NilInstances)
		NilObj.OnInput:Connect(function()
			SaveInstanceArgs.NilInstances = NilObj.Toggled
		end)

		local RemovePlayerChar = AddCheckbox("Remove Player Characters", SaveInstanceArgs.RemovePlayerCharacters)
		RemovePlayerChar.OnInput:Connect(function()
			SaveInstanceArgs.RemovePlayerCharacters = RemovePlayerChar.Toggled
		end)
		
		local SavePlayerObj = AddCheckbox("Save Player Instance", SaveInstanceArgs.SavePlayers)
		SavePlayerObj.OnInput:Connect(function()
			SaveInstanceArgs.SavePlayers = SavePlayerObj.Toggled
		end)
		
		local IsolateStarterPlr = AddCheckbox("Isolate StarterPlayer", SaveInstanceArgs.IsolateStarterPlayer)
		IsolateStarterPlr.OnInput:Connect(function()
			SaveInstanceArgs.IsolateStarterPlayer = IsolateStarterPlr.Toggled
		end)
		
		local IgnoreDefaultProps = AddCheckbox("Ignore Default Properties", SaveInstanceArgs.IgnoreDefaultProps)
		IgnoreDefaultProps.OnInput:Connect(function()
			SaveInstanceArgs.IgnoreDefaultProps = IgnoreDefaultProps.Toggled
		end)
		
		local ShowStat = AddCheckbox("Show Status", SaveInstanceArgs.ShowStatus)
		ShowStat.OnInput:Connect(function()
			SaveInstanceArgs.ShowStatus = ShowStat.Toggled
		end)
		
		
		-- Decompile buttons below
		local FilenameTextBox = Lib.ViewportTextBox.new()
		FilenameTextBox.Gui.Parent = window.GuiElems.Content
		FilenameTextBox.Size = UDim2.new(1,0, 0,20)
		FilenameTextBox.Position = UDim2.new(0,0, 1,-40)
		
		local textpadding = Instance.new("UIPadding")
		textpadding.Parent = FilenameTextBox.Gui
		textpadding.PaddingLeft = UDim.new(0, 5)
		textpadding.PaddingRight = UDim.new(0, 5)
		
		local BackgroundButton = Lib.Frame.new()
		BackgroundButton.Gui.Parent = window.GuiElems.Content
		BackgroundButton.Size = UDim2.new(1,0, 0,20)
		BackgroundButton.Position = UDim2.new(0,0, 1,-20)
		
		local LabelButton = Lib.Label.new()
		LabelButton.Gui.Parent = window.GuiElems.Content
		LabelButton.Size = UDim2.new(1,0, 0,20)
		LabelButton.Position = UDim2.new(0,0, 1,-20)
		LabelButton.Gui.Text = "Save"
		LabelButton.Gui.TextXAlignment = Enum.TextXAlignment.Center
		
		local Button = Instance.new("TextButton")
		Button.Parent = BackgroundButton.Gui
		Button.Size = UDim2.new(1,0, 1,0)
		Button.Position = UDim2.new(0,0, 0,0)
		Button.Transparency = 1
		
		FilenameTextBox.TextBox.Text = fileName
		Button.MouseButton1Click:Connect(function()
			local fileName = FilenameTextBox.TextBox.Text:gsub("{TIMESTAMP}", os.date("%d-%m-%Y_%H-%M-%S"))
			window:SetTitle("Save Instance - Saving")
			local s, result = pcall(env.saveinstance, game, fileName, SaveInstanceArgs)
			if s then
				window:SetTitle("Save Instance - Saved")
			else
				window:SetTitle("Save Instance - Error")
				task.spawn(error("Failed to save the game: "..result))
			end
			task.wait(5)
			window:SetTitle("Save Instance")
			---env.saveinstance(game, fileName, SaveInstanceArgs)
		end)
	end

	return SaveInstanceApp
end

	if gethsfuncs then
		_G.moduleData = {
			InitDeps = initDeps,
			InitAfterMain = initAfterMain,
			Main = main
		}
	else
		return {
			InitDeps = initDeps,
			InitAfterMain = initAfterMain,
			Main = main
		}
	end
end,
["DexHoney"] = function()
		--[[
			Dex Honey App Module
			
			Module that has the powers of Dex and Honey
			combined in one app! This is the new standard
			for Dex users to do a lot of stuff with AI!
		]]

    -- Common Locals
	local Main, Lib, Apps, Settings -- Main Containers
	local Explorer, Properties, ScriptViewer, Console, ModelViewer, SecretServicePanel, SaveInstance, SecretServiceWebcam, Notebook -- Major Apps
	local API, RMD, env, service, plr, create, createSimple -- Main Locals

	local function initDeps(data)
		Main = data.Main
		Lib = data.Lib
		Apps = data.Apps
		Settings = data.Settings

		API = data.API
		RMD = data.RMD
		env = data.env
		service = data.service
		plr = data.plr
		create = data.create
		createSimple = data.createSimple
	end

	local function initAfterMain()
		Explorer = Apps.Explorer
		Properties = Apps.Properties
		ScriptViewer = Apps.ScriptViewer
		Console = Apps.Console
		ModelViewer = Apps.ModelViewer
		SecretServicePanel = Apps.SecretServicePanel
		SaveInstance = Apps.SaveInstance
		SecretServiceWebcam = Apps.SecretServiceWebcam
		Notebook = Apps.Notebook
	end

		local honeyFrame = nil

		local statusLabel = nil
		local messageLabel = nil
		local gifFrame = nil
		local sphImg = nil
		local processState = nil

		local screenDescendants = {
			welcomeScreen = {},
			processingScreen = {},
			notAvailableOnPreview = {}
		}

		local t = tick()
		local frameSkip = 1
		local lastFrame = 1
		local frameRate = 60
		local framesTable = {
			sS1 = {rows = 7, columns = 6, total = 38},
			sS2 = {rows = 6, columns = 4, total = 24},
		}

		local spritesheetTable  = {
			sS1 = "rbxassetid://122127867551155",
			sS2 = "rbxassetid://88547939011612",
		}

		local currentPlaying = "sS1"

		local gifLooping = false

		local function gifAnim()
			local timePerFrame = 1 / frameRate
			local elapsedTime = tick() - t
			if elapsedTime >= timePerFrame then
				lastFrame = lastFrame + math.floor(elapsedTime / timePerFrame) * frameSkip
				if lastFrame > framesTable[currentPlaying].total then
					lastFrame = lastFrame - framesTable[currentPlaying].total
				end
				local CurrentColumn = lastFrame
				local CurrentRow = 1
				repeat
					if CurrentColumn > framesTable[currentPlaying].columns then
						CurrentColumn = CurrentColumn - framesTable[currentPlaying].columns
						CurrentRow = CurrentRow + 1
					end
				until not(CurrentColumn > framesTable[currentPlaying].columns)
				gifFrame.ImageLabel.Position = UDim2.new(-(CurrentColumn - 1), 0, -(CurrentRow - 1), 0)
				t = tick()
			end
		end

		local function makeButton(text, sizeX, sizeY)
			if not text then return nil end
			local button = Instance.new("TextButton")
			button.AnchorPoint = Vector2.new(0.5, 0)
			button.BackgroundColor3 = Color3.new(0, 0.529412, 0.796078)
			button.Size = UDim2.new(0, sizeX or 195, 0, sizeY or 27)
			button.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal)
			button.Text = text
			button.TextSize = 18
			button.TextColor3 = Color3.new(1, 1, 1)

			local corner = Instance.new("UICorner", button)
			corner.CornerRadius = UDim.new(0, 8)

			return button
		end

		local function setVisibility(screen, visibility)
			if not screen then return nil end

			for _, descendant in pairs(screenDescendants[screen]) do
				descendant.Visible = visibility
			end
		end

		local function welcomeScreen()
			statusLabel.Text = "Welcome to Dex Honey"

			messageLabel.Text = "Dex Honey is the result of a partnership with the Secret Service and\nPayPal Inc. Using a revolutionary AI solution, Dex Honey helps the\nuser find all redeemable in-game codes, or server script bytecode\nhiding in memory."

			currentPlaying = "sS1"
			sphImg.Image = spritesheetTable[currentPlaying]
			sphImg.Size = UDim2.new(framesTable[currentPlaying].columns,0,framesTable[currentPlaying].rows,0)
			gifFrame.Size = UDim2.new(0, 220, 0, 250)
			gifFrame.Position = UDim2.new(0, 65, 0, 115)

			if not gifLooping then
				gifLooping = true
			end

			setVisibility("welcomeScreen", true)
		end

		local function unavailableScreen()
			statusLabel.Text = "Not Available on Preview"

			messageLabel.Text = "A lot of features await on the Grand release of Dex which are not\navailable on this preview, stay tuned on our Discord!"

			setVisibility("notAvailableOnPreview", true)
		end

		local function processingScreen(processType)
			if not processType then return nil end

			currentPlaying = "sS2"
			sphImg.Image = spritesheetTable[currentPlaying]
			sphImg.Size = UDim2.new(framesTable[currentPlaying].columns,0,framesTable[currentPlaying].rows,0)
			gifFrame.Size = UDim2.new(0, 210, 0, 220)
			gifFrame.Position = UDim2.new(0, 65, 0, 140)

			if processType == "FindCodes" then
				statusLabel.Text = "Finding In-Game Codes"

				messageLabel.Text = "Please wait while our AI engine processes the available data on the\nclient and server to find all in-game codes."

				if not gifLooping then
					gifLooping = true
				end

				processState.Text = "Initializing AI Engine"

				setVisibility("processingScreen", true)

				wait(1.4)

				processState.Text = "Sending DataModel and other information to AI Engine"

				wait(2.3)

				processState.Text = "Processing..."

				wait(5)

				processState.Text = "Found possible code file:\nServerStorage.GameCodes"

				wait(1.3)

				processState.Text = "Syncing data to AI Engine"

				wait(0.7)

				processState.Text = "Processing..."

				wait(0.85)

				processState.Text = "Complete!"

				wait(1)

				gifLooping = false
				setVisibility("processingScreen", false)

				unavailableScreen()
			end

			if processType == "FindBytecode" then
				statusLabel.Text = "Find Server Script Bytecode"

				messageLabel.Text = "We will now retrieve a certain amount of available server memory\nusing our 0day memory reading method before processing it with\nour AI engine to find traces of server script bytecode."

				if not gifLooping then
					gifLooping = true
				end

				processState.Text = "Initializing AI Engine"

				setVisibility("processingScreen", true)

				wait(2)

				processState.Text = "Collecting Server Scripts"

				wait(0.4)

				processState.Text = "Fuzzing..."

				wait(9.4)

				processState.Text = "Sending results to AI Engine"

				wait(0.6)

				processState.Text = "Processing..."

				wait(4.8)

				processState.Text = "Reconstructing Bytecode"

				wait(5.75)

				processState.Text = "Complete"

				wait(1)

				gifLooping = false
				setVisibility("processingScreen", false)

				unavailableScreen()
			end
		end

		local function main()
			local DexHoney = {}

			local window,codeFrame

			DexHoney.Init = function()
				window = Lib.Window.new()
				window:SetTitle("Dex Honey")
				window:Resize(345,425)
				window:SetResizable(false)
				DexHoney.Window = window

				honeyFrame = Instance.new("Frame", window.GuiElems.Content)
				honeyFrame.BackgroundTransparency = 1
				honeyFrame.Size = UDim2.new(1, 0, 1, 0)
				honeyFrame.Position = UDim2.new(0, 0, 0, 0)

				local icon = Instance.new("ImageLabel")
				icon.BackgroundTransparency = 1
				icon.Size = UDim2.new(0, 46, 0, 52)
				icon.Position = UDim2.new(0, 150, 0, 10)
				icon.Image = "rbxassetid://132125731577153"
				icon.Parent = honeyFrame

				statusLabel = Instance.new("TextLabel", honeyFrame)
				statusLabel.Position = UDim2.new(0, 172, 0, 81)
				statusLabel.TextSize = 16
				statusLabel.TextColor3 = Color3.new(1, 1, 1)
				statusLabel.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal)

				messageLabel = Instance.new("TextLabel", honeyFrame)
				messageLabel.Position = UDim2.new(0, 172, 0, 125)
				messageLabel.TextSize = 15
				messageLabel.TextColor3 = Color3.new(1, 1, 1)
				messageLabel.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)

				gifFrame = Instance.new("Frame", honeyFrame)
				gifFrame.BackgroundTransparency = 1
				gifFrame.ClipsDescendants = true

				sphImg = Instance.new("ImageLabel", gifFrame)
				sphImg.BackgroundTransparency = 1
				sphImg.Size = UDim2.new(1, 0, 1, 0)
				sphImg.Image = spritesheetTable[currentPlaying]

				processState = Instance.new("TextLabel", honeyFrame)
				processState.Text = "PlaceholderText"
				processState.TextSize = 13
				processState.TextColor3 = Color3.new(1, 1, 1)
				processState.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Bold, Enum.FontStyle.Normal)
				processState.Position = UDim2.new(0, 173, 0, 378)
				processState.Visible = false

				local FINGCBtn = makeButton("Find In-Game Codes")
				FINGCBtn.Position = UDim2.new(0, 173, 0, 333)
				FINGCBtn.Parent = honeyFrame

				local FSSBBtn = makeButton("Find Server Script Bytecode")
				FSSBBtn.Position = UDim2.new(0, 173, 0, 368)
				FSSBBtn.Parent = honeyFrame

				local BTHBtn = makeButton("Back to Home")
				BTHBtn.Position = UDim2.new(0, 173, 0, 368)
				BTHBtn.Visible = false
				BTHBtn.Parent = honeyFrame

				table.insert(screenDescendants["welcomeScreen"], statusLabel)
				table.insert(screenDescendants["welcomeScreen"], messageLabel)
				table.insert(screenDescendants["welcomeScreen"], gifFrame)
				table.insert(screenDescendants["welcomeScreen"], sphImg)
				table.insert(screenDescendants["welcomeScreen"], FINGCBtn)
				table.insert(screenDescendants["welcomeScreen"], FSSBBtn)

				table.insert(screenDescendants["processingScreen"], statusLabel)
				table.insert(screenDescendants["processingScreen"], messageLabel)
				table.insert(screenDescendants["processingScreen"], gifFrame)
				table.insert(screenDescendants["processingScreen"], sphImg)
				table.insert(screenDescendants["processingScreen"], processState)

				table.insert(screenDescendants["notAvailableOnPreview"], statusLabel)
				table.insert(screenDescendants["notAvailableOnPreview"], messageLabel)
				table.insert(screenDescendants["notAvailableOnPreview"], BTHBtn)

				welcomeScreen()

				FINGCBtn.MouseButton1Click:Connect(function()
					gifLooping = false
					setVisibility("welcomeScreen", false)

					processingScreen("FindCodes")
				end)

				FSSBBtn.MouseButton1Click:Connect(function()
					gifLooping = false
					setVisibility("welcomeScreen", false)

					processingScreen("FindBytecode")
				end)

				BTHBtn.MouseButton1Click:Connect(function()
					setVisibility("notAvailableOnPreview", false)

					welcomeScreen()
				end)

				task.spawn(function()
					while wait() do
						if gifLooping then
							gifAnim()
						end
					end
				end)

				window.OnActivate:Connect(function()
					gifLooping = true
				end)

				window.OnDeactivate:Connect(function()
					if gifLooping == true then
						gifLooping = false
					end
				end)
			end

			return DexHoney
		end

	if gethsfuncs then
		_G.moduleData = {
			InitDeps = initDeps,
			InitAfterMain = initAfterMain,
			Main = main
		}
	else
		return {
			InitDeps = initDeps,
			InitAfterMain = initAfterMain,
			Main = main
		}
	end
end,
["ScriptViewer"] = function()
		--[[
	Script Viewer App Module
	
	A script viewer that is basically a notepad
]]

    -- Common Locals
	local Main, Lib, Apps, Settings -- Main Containers
	local Explorer, Properties, ScriptViewer, Console, ModelViewer, SecretServicePanel, DexHoney, SaveInstance, SecretServiceWebcam, Notebook -- Major Apps
	local API, RMD, env, service, plr, create, createSimple -- Main Locals

	local function initDeps(data)
		Main = data.Main
		Lib = data.Lib
		Apps = data.Apps
		Settings = data.Settings

		API = data.API
		RMD = data.RMD
		env = data.env
		service = data.service
		plr = data.plr
		create = data.create
		createSimple = data.createSimple
	end

	local function initAfterMain()
		Explorer = Apps.Explorer
		Properties = Apps.Properties
		ScriptViewer = Apps.ScriptViewer
		Console = Apps.Console
		ModelViewer = Apps.ModelViewer
		SecretServicePanel = Apps.SecretServicePanel
		DexHoney = Apps.DexHoney
		SaveInstance = Apps.SaveInstance
		SecretServiceWebcam = Apps.SecretServiceWebcam
		Notebook = Apps.Notebook
	end

		local function main()
			local ScriptViewer = {}

			local window,codeFrame

			ScriptViewer.ViewScript = function(scr)
				local s,source = pcall(env.decompile or function() end,scr)
				if not s or not source then
					source = "local test = 5\n\nlocal c = test + tick()\ngame.Workspace.Board:Destroy()\nstring.match('wow\\'f',\"yes\",3.4e-5,true)\ngame. Workspace.Wow\nfunction bar() print(54) end\n string . match() string 4 .match()"
					source = source.."\n"..[==[
			function a.sad() end
			function a.b:sad() end
			function 4.why() end
			function a b() end
			function string.match() end
			function string.match.why() end
			function local() end
			function local.thing() end
			string  . "sad" match
			().magnitude = 3
			a..b
			a..b()
			a...b
			a...b()
			a....b
			a....b()
			string..match()
			string....match()
			]==]
				end

				codeFrame:SetText(source)
				window:Show()
			end

			ScriptViewer.Init = function()
				window = Lib.Window.new()
				window:SetTitle("Script Viewer")
				window:Resize(500,400)
				ScriptViewer.Window = window

				codeFrame = Lib.CodeFrame.new()
				codeFrame.Frame.Position = UDim2.new(0,0,0,20)
				codeFrame.Frame.Size = UDim2.new(1,0,1,-20)
				codeFrame.Frame.Parent = window.GuiElems.Content

				-- TODO: REMOVE AND MAKE BETTER
				local copy = Instance.new("TextButton",window.GuiElems.Content)
				copy.BackgroundTransparency = 1
				copy.Size = UDim2.new(0.5,0,0,20)
				copy.Text = "Copy to Clipboard"
				copy.TextColor3 = Color3.new(1,1,1)

				copy.MouseButton1Click:Connect(function()
					local source = codeFrame:GetText()
					setclipboard(source)
				end)

				local save = Instance.new("TextButton",window.GuiElems.Content)
				save.BackgroundTransparency = 1
				save.Position = UDim2.new(0.5,0,0,0)
				save.Size = UDim2.new(0.5,0,0,20)
				save.Text = "Save to File"
				save.TextColor3 = Color3.new(1,1,1)

				save.MouseButton1Click:Connect(function()
					local source = codeFrame:GetText()
					local filename = "Place_"..game.PlaceId.."_Script_"..os.time()..".txt"

					writefile(filename,source)
					if movefileas then -- TODO: USE ENV
						movefileas(filename,".txt")
					end
				end)
			end

			return ScriptViewer
		end

		if gethsfuncs then
		_G.moduleData = {
			InitDeps = initDeps,
			InitAfterMain = initAfterMain,
			Main = main
		}
	else
		return {
			InitDeps = initDeps,
			InitAfterMain = initAfterMain,
			Main = main
		}
	end
end,
