local function main()

	local DataStoreEditor = {}
	local window

	DataStoreEditor.Init = function()

		window = Lib.Window.new()
		window:SetTitle("DataStore Editor")
		window:Resize(205,530)

		DataStoreEditor.Window = window

		local List = Instance.new("Frame")
		List.Name = "List"
		List.Parent = window.GuiElems.Content
		List.BackgroundTransparency = 1
		List.Size = UDim2.new(1,0,1,0)

		local PlayerData = Instance.new("TextButton")
		PlayerData.Parent = List
		PlayerData.Size = UDim2.new(1,0,0,20)
		PlayerData.BackgroundTransparency = 1
		PlayerData.Text = ""
		PlayerData.AutoButtonColor = false

		local Indent = Instance.new("Frame")
		Indent.Parent = PlayerData
		Indent.Position = UDim2.new(0,20,0,0)
		Indent.Size = UDim2.new(1,-20,1,0)
		Indent.BackgroundTransparency = 1

		local EntryName = Instance.new("TextLabel")
		EntryName.Parent = Indent
		EntryName.Position = UDim2.new(0,26,0,0)
		EntryName.Size = UDim2.new(1,-26,1,0)
		EntryName.BackgroundTransparency = 1
		EntryName.Text = "PlayerData"
		EntryName.TextColor3 = Color3.fromRGB(220,220,220)
		EntryName.TextXAlignment = Enum.TextXAlignment.Left

		local Expand = Instance.new("TextButton")
		Expand.Parent = Indent
		Expand.Position = UDim2.new(0,-20,0,0)
		Expand.Size = UDim2.new(0,20,0,20)
		Expand.BackgroundTransparency = 1
		Expand.Text = ""

local PlayersFrame = Instance.new("ScrollingFrame")
PlayersFrame.Parent = List
PlayersFrame.Position = UDim2.new(0, 0, 0.0416795851, 0)
PlayersFrame.Size = UDim2.new(1,0,1,-20)
PlayersFrame.BackgroundTransparency = 1
PlayersFrame.Visible = false

PlayersFrame.CanvasSize = UDim2.new(0,0,0,0)
PlayersFrame.ScrollBarThickness = 6
PlayersFrame.BorderSizePixel = 0

PlayersFrame.TopImage = ""
PlayersFrame.MidImage = ""
PlayersFrame.BottomImage = ""

local layout = Instance.new("UIListLayout")
layout.Parent = PlayersFrame
layout.Parent = PlayersFrame
layout.SortOrder = Enum.SortOrder.LayoutOrder
layout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
	PlayersFrame.CanvasSize = UDim2.new(
		0,
		0,
		0,
		layout.AbsoluteContentSize.Y
	)
end)

		local PlaceHolderEntry = Instance.new("TextButton")
		PlaceHolderEntry.Visible = false
		PlaceHolderEntry.Size = UDim2.new(1,0,0,20)
		PlaceHolderEntry.BackgroundTransparency = 1
		PlaceHolderEntry.Parent = List

		local Indent2 = Instance.new("Frame")
		Indent2.Parent = PlaceHolderEntry
		Indent2.Position = UDim2.new(0,40,0,0)
		Indent2.Size = UDim2.new(1,-40,1,0)
		Indent2.Name = "Indent"
		Indent2.BackgroundTransparency = 1

		local EntryName2 = Instance.new("TextLabel")
		EntryName2.Parent = Indent2
		EntryName2.Position = UDim2.new(0,26,0,0)
		EntryName2.Size = UDim2.new(1,-26,1,0)
		EntryName2.Name = "EntryName"
		EntryName2.BackgroundTransparency = 1
		EntryName2.TextColor3 = Color3.fromRGB(220,220,220)
		EntryName2.TextXAlignment = Enum.TextXAlignment.Left

		local Players = game:GetService("Players")
		local ListedPlayers = {}

		local function SetEntryColor(entry)
			local color = Color3.fromRGB(13,104,202)

			for _,ent in pairs(List:GetDescendants()) do
				if ent:IsA("Frame") and ent.BackgroundColor3 == color then
					ent.BackgroundTransparency = 1
				end
			end

			if entry:FindFirstChild("Indent") then
				entry.Indent.BackgroundColor3 = color
				entry.Indent.BackgroundTransparency = 0
			end
		end

		Expand.MouseButton1Down:Connect(function()
			PlayersFrame.Visible = not PlayersFrame.Visible
			Expand.Rotation = PlayersFrame.Visible and 90 or 0
		end)

		local function Refresh()
		 table.sort(ListedPlayers)
			for _,v in pairs(PlayersFrame:GetChildren()) do
				if v.Name == "EntryFrameData" then
					v:Destroy()
				end
			end

for i,p in ipairs(ListedPlayers) do
	local new = PlaceHolderEntry:Clone()

	new.Visible = true
	new.Name = "EntryFrameData"
	new.LayoutOrder = i   -- important

	new.Parent = PlayersFrame
	new.Indent.EntryName.Text = p

				new.MouseButton1Down:Connect(function()
					SetEntryColor(new)
					Properties.DisplayValueEditor(game.Players:FindFirstChild(p))
				end)
			end
		end

		Players.PlayerAdded:Connect(function(plr)
			table.insert(ListedPlayers,plr.Name)
			Refresh()
		end)

		Players.PlayerRemoving:Connect(function(plr)
			local i = table.find(ListedPlayers,plr.Name)
			if i then
				table.remove(ListedPlayers,i)
			end
			Refresh()
		end)

		for _,plr in pairs(Players:GetPlayers()) do
			table.insert(ListedPlayers,plr.Name)
		end

		Refresh()
	end

	return DataStoreEditor
end

if gethsfuncs then
	_G.moduleData = {
		InitDeps = initDeps,
		InitAfterMain = initAfterMain,
		Main = main
	}
else
	return {
		InitDeps = initDeps,
		InitAfterMain = initAfterMain,
		Main = main
	}
end
end,
