-- Fuzzy match with Levenshtein distance ≤1
local function levenshtein(a, b)
	local m, n = #a, #b
	local dp = {}
	for i = 0, m do
		dp[i] = {}
		for j = 0, n do
			if i == 0 then
				dp[i][j] = j
			elseif j == 0 then
				dp[i][j] = i
			else
				dp[i][j] = 0
			end
		end
	end

	for i = 1, m do
		for j = 1, n do
			if a:sub(i,i) == b:sub(j,j) then
				dp[i][j] = dp[i-1][j-1]
			else
				dp[i][j] = math.min(dp[i-1][j-1]+1, dp[i][j-1]+1, dp[i-1][j]+1)
			end
		end
	end
	return dp[m][n]
end

local function fuzzyMatch(s, query)
	s = string.lower(s)
	query = string.lower(query)
	if query == "" then return true end
	return levenshtein(s, query) <= 1 or string.find(s, query, 1, true)
end

-- Updated search function
local function updateSearch(query)
	query = string.lower(query)
	for _, item in ipairs(scriptsframe:GetChildren()) do
		if item:IsA("Frame") then
			local textButton = item:FindFirstChildOfClass("TextButton")
			if textButton then
				local text = string.lower(textButton.Text)
				item.Visible = fuzzyMatch(text, query)
			end
		end
	end
end

