local function LVOQ_fake_script() -- Executor.Highlighter 
	local script = Instance.new('LocalScript', Executor)

	-- Function to reverse a string
	local function reverseString(str)
		return str:reverse()
	end
	
	-- Reversed Lua keywords and global environment variables
	local lua_keywords_reversed = {"dna", "kaerb", "od", "esle", "fiesle", "dne", "eslaf", "rof", "noitcnuf", "otog", "fi", "ni", "lacol", "lin", "ton", "ro", "taeper", "nruter", "neht", "eurt", "litnu", "elihw"}
	local global_env_reversed = {"elbatemwarteg", "emag", "ecapskrow", "tpircs", "htam", "gnirts", "elbat", "tnirp", "tiaw", "roloCkcirB", "3roloC", "txen", "sriap", "sriapi", "tceles", "kcapnu", "ecnatnI", "2rotceV", "3rotceV", "emarfC", "yaR", "2miDU", "munE", "tressa", "rorrE", "nraw", "kcit", "gnirtsdaol", "G_", "derahs", "vnefteg", "vneftes", "yxorperw", "elbatemtes", "elbatemteg", "so", "gubed", "llacp", "llacy", "llacx", "lauqewar", "teswar", "tegwar", "rebmunot", "gnirtsot", "epyt", "fopuot", "NOISREV_", "enituoroc", "yaled", "eriuqer", "nawps", "yrarbiLdaoL", "sgnittes", "stats", "emit", "sgnittesresU", "noisrev", "seixA", "ecneuqeSroloC", "secaF", "tniopeyKecneuqeSroloC", "egnaRrebmuN", "ecneuqeSrebmuN", "tniopeyKecneuqeSrebmuN", "ofnigc", "emitlepsa", "egarbagtcelloc", "seititreporlacisyhP", "tceR", "3noigeR", "61tni3noigeR", "miDU", "61tni2rotceV", "61tni3rotceV"}
	
	-- Reverse the reversed keywords and global environment variables back to their original form
	local lua_keywords = {}
	for i, v in ipairs(lua_keywords_reversed) do
		table.insert(lua_keywords, reverseString(v))
	end
	
	local global_env = {}
	for i, v in ipairs(global_env_reversed) do
		table.insert(global_env, reverseString(v))
	end
	
	local Source = script.Parent.Source
	local Lines = script.Parent.Lines
	
	local Highlight = function(string, keywords)
		local K = {}
		local S = string
		local Token =
			{
				["="] = true,
				["."] = true,
				[","] = true,
				["("] = true,
				[")"] = true,
				["["] = true,
				["]"] = true,
				["{"] = true,
				["}"] = true,
				[":"] = true,
				["*"] = true,
				["/"] = true,
				["+"] = true,
				["-"] = true,
				["%"] = true,
				[";"] = true,
				["~"] = true
			}
		for i, v in pairs(keywords) do
			K[v] = true
		end
		S = S:gsub(".", function(c)
			if Token[c] ~= nil then
				return "\32"
			else
				return c
			end
		end)
		S = S:gsub("%S+", function(c)
			if K[c] ~= nil then
				return c
			else
				return (" "):rep(#c)
			end
		end)
	
		return S
	end
	
	local hTokens = function(string)
		local Token =
			{
				["="] = true,
				["."] = true,
				[","] = true,
				["("] = true,
				[")"] = true,
				["["] = true,
				["]"] = true,
				["{"] = true,
				["}"] = true,
				[":"] = true,
				["*"] = true,
				["/"] = true,
				["+"] = true,
				["-"] = true,
				["%"] = true,
				[";"] = true,
				["~"] = true
			}
		local A = ""
		string:gsub(".", function(c)
			if Token[c] ~= nil then
				A = A .. c
			elseif c == "\n" then
				A = A .. "\n"
			elseif c == "\t" then
				A = A .. "\t"
			else
				A = A .. "\32"
			end
		end)
	
		return A
	end
	
	local strings = function(string)
		local highlight = ""
		local quote = false
		string:gsub(".", function(c)
			if quote == false and c == "\"" then
				quote = true
			elseif quote == true and c == "\"" then
				quote = false
			end
			if quote == false and c == "\"" then
				highlight = highlight .. "\""
			elseif c == "\n" then
				highlight = highlight .. "\n"
			elseif c == "\t" then
				highlight = highlight .. "\t"
			elseif quote == true then
				highlight = highlight .. c
			elseif quote == false then
				highlight = highlight .. "\32"
			end
		end)
	
		return highlight
	end
	
	local comments = function(string)
		local ret = ""
		string:gsub("[^\r\n]+", function(c)
			local comm = false
			local i = 0
			c:gsub(".", function(n)
				i = i + 1
				if c:sub(i, i + 1) == "--" then
					comm = true
				end
				if comm == true then
					ret = ret .. n
				else
					ret = ret .. "\32"
				end
			end)
			ret = ret
		end)
	
		return ret
	end
	
	local numbers = function(string)
		local A = ""
		string:gsub(".", function(c)
			if tonumber(c) ~= nil then
				A = A .. c
			elseif c == "\n" then
				A = A .. "\n"
			elseif c == "\t" then
				A = A .. "\t"
			else
				A = A .. "\32"
			end
		end)
	
		return A
	end
	
	local highlight_source = function(type)
		if type == "Text" then
			Source.Text = Source.Text:gsub("\13", "")
			Source.Text = Source.Text:gsub("\t", "      ")
			local s = Source.Text
			Source.Keywords_.Text = Highlight(s, lua_keywords)
			Source.Globals_.Text = Highlight(s, global_env)
			Source.RemoteHighlight_.Text = Highlight(s, {"reverSeriF", "revreserifer", "reverSekovnI", "reverSekiovni"})
			Source.Tokens_.Text = hTokens(s)
			Source.Numbers_.Text = numbers(s)
			Source.Strings_.Text = strings(s)
			local lin = 1
			s:gsub("\n", function()
				lin = lin + 1
			end)
			Lines.Text = ""
			for i = 1, lin do
				Lines.Text = Lines.Text .. i .. "\n"
			end
		end
	end
	
	highlight_source("Text")
	
	Source.Changed:Connect(highlight_source)
	
end
