    bottomDecal.Face = 4
    bottomDecal.Parent = shockRing
    
    return shockRing
end


local players = game:GetService("Players")
function doDamage(hit)
    local humanoid = hit.Parent:FindFirstChild("Humanoid")
    local vCharacter = Tool.Parent
    local vPlayer = players:GetPlayerFromCharacter(vCharacter)
    local hum = vCharacter:FindFirstChild("Humanoid") -- non-nil if tool held by a character
    if humanoid~=nil and humanoid ~= hum and hum ~= nil then
        tagHumanoid(humanoid, vPlayer)
        humanoid:TakeDamage(humanoid.MaxHealth)
        if humanoid.Health <= 0 then
            local c = hit.CFrame
            hit.CFrame = CFrame.new(hit.Position)
            hit.CFrame = c
        end
        task.delay(1, function() untagHumanoid(humanoid) end)
        else
            local c = hit.CFrame    hit:BreakJoints()    hit.CFrame = CFrame.new(hit.Position)    hit.CFrame = c
        end
    end
    
    
    function tagHumanoid(humanoid, player)
        local creator_tag = Instance.new("ObjectValue")
        creator_tag.Value = player
        creator_tag.Name = "creator"
        creator_tag.Parent = humanoid
    end
    
    function untagHumanoid(humanoid)
        if humanoid ~= nil then
            local tag = humanoid:FindFirstChild("creator")
            if tag ~= nil then
                tag.Parent = nil
            end
        end
    end
    
    local function isAnchorProtected(obj)
        if not obj.Anchored then
            return false
        else
            return not modelSettings.DestroyAnchored or obj:GetMass() > modelSettings.MaxMass
        end
    end
    
    function blow(root, pos, notme)
        local plr = game:GetService("Players").LocalPlayer
        local char = plr and plr.Character
        if not char then return end
        
        for _,obj in pairs(root:GetDescendants()) do
            if obj:IsA("BasePart") and not obj:IsDescendantOf(char) then
                if (not isAnchorProtected(obj)) and (((pos - obj.Position) * Vector3.new(1, 0, 1)).magnitude < 96) and (pos.y <= obj.Position.y + 8) and (pos.y >= obj.Position.y - 8) then
                    obj.Anchored = false
                    task.delay((pos - obj.Position).magnitude / 96, function()    doDamage(obj)    obj.Velocity = ((obj.Position - pos).unit + Vector3.new(0, 0.5, 0)) * 96 + obj.Velocity    obj.RotVelocity = obj.RotVelocity + Vector3.new(obj.Position.z - pos.z, 0, pos.x - obj.Position.x).unit * 40    end)
                    end
                    end
                    end
                    end
                        
                        function attack()
                            local anim = Instance.new("StringValue")
                            anim.Name = "toolanim"
                            anim.Value = "Slash"
                            anim.Parent = Tool
                            wait(0.2)
                            
                            print("Blasting!")
                            
                            local pos = hammer.CFrame * (Vector3.new(0, 1.4, 0) * hammer.Mesh.Scale)
                            
                            blow(workspace, pos, Tool.Parent)
                            
                            local shockRing = newShockRing()
                            
                            shockRing.CFrame = CFrame.new(pos)
                            shockRing.Parent = Tool
                            for x = 1, 29 do
                                task.delay(x / 30, function()    shockRing.Size = Vector3.new(0, 0.4, 0) + Vector3.new(6.4, 0, 6.4) * x    end)
                                end
                                    task.delay(1, function() shockRing.Parent = nil end)
                                    end
                                        
                                        
                                        Tool.Enabled = true
                                        function onActivated()
                                            
                                            if not Tool.Enabled then
                                                return
                                            end
                                            
                                            Tool.Enabled = false
                                            
                                            local character = Tool.Parent;
                                            local humanoid = character.Humanoid
                                            if humanoid == nil then
                                                print("Humanoid not found")
                                                return 
                                            end
                                            
                                            local newBoom = hammer.Boom:Clone()
                                            newBoom.Parent = hammer
                                            newBoom:Play()
                                            task.delay(6,newBoom.Destroy,newBoom)
                                            attack()
                                            
                                            task.wait(0.5)
                                            
                                            Tool.Enabled = true
                                        end
                                        
                                        
                                        Tool.Activated:Connect(onActivated)
                                        --wait(2)
                                        Tool.Parent = game:GetService("Players").LocalPlayer.Backpack
