local function FMKRG_fake_script() -- DragUi.LocalScript 
	local script = Instance.new('LocalScript', DragUi)

	local UserInputService = game:GetService("UserInputService")
	
	local gui = script.Parent
	
	local dragging
	local dragInput
	local dragStart
	local startPos
	
	local function update(input)
		local delta = input.Position - dragStart
		gui.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
	end
	
	gui.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragStart = input.Position
			startPos = gui.Position
	
			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)
	
	gui.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
			dragInput = input
		end
	end)
	
	UserInputService.InputChanged:Connect(function(input)
		if input == dragInput and dragging then
			update(input)
		end
	end)
end
coroutine.wrap(FMKRG_fake_script)()
end)

local ppeeh = createScriptButton("pee", function(btn)
	btn.Text = "Loading... Please Wait"
	task.wait(0.5)
	btn.Text = "pee"
	local Player = game.Players.LocalPlayer
local Character = Player.Character or Player.CharacterAdded:Wait()
local Head = Character:WaitForChild("Head")
local Torso = Character:FindFirstChild("Torso") or Character:WaitForChild("UpperTorso") -- Compatibility for R15

-- Function to create a weld
local function Weld(x, y)
    local W = Instance.new("Weld")
    W.Part0 = x
    W.Part1 = y
    local CJ = CFrame.new(x.Position)
    local C0 = x.CFrame:inverse() * CJ
    local C1 = y.CFrame:inverse() * CJ
    W.C0 = C0
    W.C1 = C1
    W.Parent = x
end

-- Create Breath Part
local Breath = Instance.new("Part")
Breath.Name = "Breath"
Breath.Parent = Head
Breath.CFrame = Torso.CFrame * CFrame.new(0, -1, 0)
Breath.CanCollide = false
Breath.Transparency = 1
Breath.Size = Vector3.new(0.05, 0.05, 0.05)

-- Particle Emitter for Breath
