local function BFFJPB_fake_script() -- b_2.Script 
	local script = Instance.new('Script', b_2)

	function click()
		local Players = game:GetService("Players")
	
		-- FunÃ§Ã£o para criar e exibir o Hint animado na cabeÃ§a dos jogadores
		local function exibirHintAnimado()
			-- Percorrer todos os jogadores no jogo
			for _, player in pairs(Players:GetPlayers()) do
				-- Verifica se o jogador tem um personagem
				if player.Character and player.Character:FindFirstChild("Head") then
					-- Criar o BillboardGui que serÃ¡ usado para mostrar a mensagem na cabeÃ§a
					local billboard = Instance.new("BillboardGui")
					billboard.Size = UDim2.new(0, 400, 0, 50)  -- Tamanho da Ã¡rea onde o texto serÃ¡ exibido
					billboard.Adornee = player.Character.Head  -- Posiciona o BillboardGui na cabeÃ§a do personagem
					billboard.StudsOffset = Vector3.new(0, 3, 0)  -- DistÃ¢ncia da cÃ¢mera (ajuste para mais alto ou mais baixo)
					billboard.Parent = player.Character.Head  -- Coloca o BillboardGui na cabeÃ§a do personagem
	
					-- Criar o TextLabel dentro do BillboardGui
					local textLabel = Instance.new("TextLabel")
					textLabel.Size = UDim2.new(1, 0, 1, 0)  -- Preenche toda a Ã¡rea do BillboardGui
					textLabel.TextColor3 = Color3.fromRGB(255, 0, 0)  -- Cor do texto (vermelho)
					textLabel.TextStrokeTransparency = 0.5  -- TransparÃªncia da borda do texto
					textLabel.TextSize = 30  -- Tamanho do texto
					textLabel.BackgroundTransparency = 1  -- Sem fundo para o TextLabel
					textLabel.Text = ""  -- ComeÃ§a sem texto
					textLabel.Parent = billboard  -- Coloca o TextLabel dentro do BillboardGui
	
					-- A mensagem que queremos "digitar"
					local mensagem = "1X1X1X1"
	
					-- FunÃ§Ã£o que vai "digitar" a mensagem
					for i = 1, #mensagem do
						textLabel.Text = string.sub(mensagem, 1, i)  -- Mostra uma parte da mensagem atÃ© o Ã­ndice i
						wait(0.1)  -- Espera um pequeno intervalo para a animaÃ§Ã£o (ajuste esse valor para mais rÃ¡pido ou devagar)
					end
				end
			end
		end
	
		-- Chama a funÃ§Ã£o para exibir o hint animado
		exibirHintAnimado()
	
	end
	
	script.Parent.MouseButton1Down:Connect(click)
end
