local Ui = Instance.new("ImageLabel")
Ui.Size = UDim2.new(0, 393, 0, 300)
Ui.Position = UDim2.new(0, 180, 0, 0)
Ui.Image = "rbxassetid://82356005646259"
Ui.BackgroundTransparency = 1  -- พื้นหลังโปร่ง
