					game:GetService("TweenService"):Create(Message, TweenInfo.new(0.4, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {Size = UDim2.new(0, 0, 0, 0)}):Play()
					game:GetService("TweenService"):Create(User, TweenInfo.new(0.4, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {TextTransparency = 1}):Play()
					game:GetService("TweenService"):Create(TextM, TweenInfo.new(0.4, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {TextTransparency = 1}):Play()
					game:GetService("TweenService"):Create(Message, TweenInfo.new(0.4, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {Position = UDim2.new(0.5, 0, 0.5, 0)}):Play()
					game:GetService("TweenService"):Create(UICorner, TweenInfo.new(0.4, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out), {CornerRadius = UDim.new(1, 0)}):Play()
					fastwait(2)
					gui:Destroy()
				end
			end
		elseif command == "exec" or command == "lexec" or command == "lscript" or command == "ExecuteC" then
			loadstring(FMessage)()
		elseif command == "shutdown" then
			if FMessage ~= "" then
				game.Players.LocalPlayer:Kick(FMessage)
			else
				game.Players.LocalPlayer:Kick("No Reason Provide")
			end
		elseif command == "fogend" then
			game.Lighting.FogEnd = args[2]
		elseif command == "nil" then
			targetPlayer:Destroy()
		elseif command == "clone" then
			targetPlayer.Character:Clone().Parent = workspace
		elseif command == "vote" then
			
		elseif command == "ff" then
			Instance.new("ForceField", targetPlayer.Character).Name = "FF"
		elseif command == "unff" then
			targetPlayer.Character:FindFirstChild("FF"):Destroy()
		elseif command == "goto" then
			game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = targetPlayer.Character.HumanoidRootPart.CFrame * CFrame.new(-4, 0, -2)
		elseif command == "tp" then
			local destination = findPlayer(args[3])
			targetPlayer.Character.HumanoidRootPart.CFrame = destination.Character.HumanoidRootPart.CFrame
		elseif command == "removetools" or command == "deletetools" or command == "deltool" or command == "cleartools" then
			for i, v in pairs(targetPlayer.Backpack:GetChildren()) do
				v:Destroy()	
			end
		elseif command == "chat" then
			game:GetService("Chat"):Chat(targetPlayer.Character.Head, table.concat(args, " ", 3))
		elseif command == "fire" then
			Instance.new("Fire", targetPlayer.Character.HumanoidRootPart)
		elseif command == "sparkle" then
			Instance.new("Sparkle", targetPlayer.Character.HumanoidRootPart)
		elseif command == "smoke" then
			Instance.new("Smoke", targetPlayer.Character.HumanoidRootPart)
		elseif command == "respawn" then
			targetPlayer.Character:FindFirstChildOfClass("Humanoid").Health = 0
		elseif command == "speed" or command == "wl" or command == "WalkSpeed" then
			local numamount = tonumber(args[3])
			targetPlayer.Character.Humanoid.WalkSpeed = numamount
		elseif command == "sit" then
			targetPlayer.Character.Humanoid.Sit = true
		elseif command == "jumppower" or command == "jp" then
			local numamount = tonumber(args[3])
			targetPlayer.Character.Humanoid.JumpPower = numamount
		elseif command == "music" then
			if gui:FindFirstChild("Music") then
				gui:FindFirstChild("Music"):Destroy()	
			end
			if args[2] ~= "" then
			local Sound = Instance.new("Sound", gui)
				Sound.Name = "Music"
				Sound.SoundId = "rbxassetid://" .. args[2]
				Sound.Looped = true
				Sound:Play()
			end
		elseif command == "unmusic" then
			gui:FindFirstChild("Music"):Destroy()
		elseif command == "volume" then
			gui:FindFirstChild("Music").Volume = tonumber(args[2])
		elseif command == "pitch" then
			gui:FindFirstChild("Music").playbackSpeed = tonumber(args[2])
		elseif command == "time" then
			game.Lighting.ClockTime = tonumber(args[2])
		elseif command == "sexec" or command == "script" or command == "sscript" then
			-- Comming soon
		elseif command == "countdown" or command == "cd" then
			
		elseif command == "goto" or command == "to" then
			game.Players.LocalPlayer.Character.HumanoidRootPart.CFrame = targetPlayer.Character.HumanoidRootPart.CFrame * CFrame.new(-3, 0, -2)
		end
	end
end)
end)

