local function createOrb(char)
	if orbClicked then return end
	local root = char:WaitForChild("HumanoidRootPart")
	local humanoid = char:WaitForChild("Humanoid")

	local orb = Instance.new("Part")
	orb.Name = "AdminCube"
	orb.Size = Vector3.new(3,3,3)
	orb.Material = Enum.Material.Neon
	orb.Color = Color3.fromRGB(135, 206, 250)
	orb.Transparency = 0.67
	orb.Anchored = true
	orb.CanCollide = false
	orb.Shape = Enum.PartType.Block
	orb.Parent = workspace

	local core = Instance.new("Part")
	core.Size = Vector3.new(1.2,1.2,1.2)
	core.Material = Enum.Material.Neon
	core.Color = Color3.fromRGB(245, 250, 255)
	core.Transparency = 0.1
	core.Anchored = true
	core.CanCollide = false
	core.Shape = Enum.PartType.Block
	core.Parent = orb

	local light = Instance.new("PointLight", orb)
	light.Color = orb.Color
	light.Range = 15
	light.Brightness = 1.8

	local click = Instance.new("ClickDetector")
	click.MaxActivationDistance = 20
	click.Parent = orb

	local textPart = Instance.new("Part")
	textPart.Size = Vector3.new(0.2,0.2,0.2)
	textPart.Anchored = true
	textPart.CanCollide = false
	textPart.Transparency = 1
	textPart.Parent = workspace

	local billboard = Instance.new("BillboardGui")
	billboard.Adornee = textPart
	billboard.AlwaysOnTop = true
	billboard.Size = UDim2.new(0,150,0,30)
	billboard.StudsOffset = Vector3.new(0,0,0)
	billboard.Parent = textPart

	local label = Instance.new("TextLabel")
	label.Size = UDim2.new(1,0,1,0)
	label.BackgroundTransparency = 1
	label.Text = "You are Admin! Level: 4"
	label.TextColor3 = Color3.fromRGB(0, 255, 255)
	label.TextScaled = true
	label.TextStrokeTransparency = 0
	label.TextStrokeColor3 = Color3.fromRGB(0, 170, 255)
	label.TextXAlignment = Enum.TextXAlignment.Center
	label.TextYAlignment = Enum.TextYAlignment.Center
	label.Parent = billboard

	click.MouseClick:Connect(function(plr)
		if plr == player then
			orbClicked = true
			orb:Destroy()
			core:Destroy()
			textPart:Destroy()
		end
	end)

	humanoid.Died:Connect(function()
		if orb.Parent then orb:Destroy() end
		if core.Parent then core:Destroy() end
		if textPart.Parent then textPart:Destroy() end
	end)

	local radius = 5
	local height = 1.3
	local speed = 0.6
	local angle = 0

	RunService.RenderStepped:Connect(function(dt)
		if not root or not root.Parent or not orb.Parent then return end
		angle += speed * dt
		local x = math.cos(angle) * radius
		local z = math.sin(angle) * radius
		local offset = Vector3.new(x,height,z)
		local orbCFrame = root.CFrame * CFrame.new(offset) * CFrame.Angles(0, angle, math.rad(20))
		orb.CFrame = orbCFrame
		core.CFrame = orbCFrame
		textPart.CFrame = orbCFrame * CFrame.new(0,2,0)
	end)
end

if player.Character then
	createOrb(player.Character)
end

