    -- | FUNCTIONS | --
        function ADD_COMMAND(C, U, A, F)
            table.insert(COMMANDS, {CMD = C, USAGE = U, ALIAS = A, FUNCTION = F})
        end
        
        function CHECK_ADMIN(I)
            if I == LP.UserId or TABLE(ADMINS, I) then
                return true
            end
            return false
        end
        
        function COMMAND(S, SP)
            if CHECK_ADMIN(SP.UserId) then
                repeat
                    S = S:gsub('  ', ' ')
                until not S:find('  ')
                if S:sub(1, -#S) == ' ' then
                    S = S:sub(2, #S)
                end
                local GCMD = GET_COMMAND(S)
                local FCMD = FIND_COMMAND(GCMD[1])
                if FCMD then
                    ARGS = GET_ARGS(S:sub(#GCMD[1] + 2))
                    pcall(function()
                        FCMD.FUNCTION(ARGS, SP)
                    end)
                    local LOG = '[' .. TIME() .. '] ' .. '[' .. SP.Name .. '] : "' .. PREFIX .. FCMD.CMD
                    for i,v in pairs(ARGS) do
                        LOG = LOG .. ' ' .. v
                    end
                    LOGS_TAB.Logs.CanvasSize = LOGS_TAB.Logs.CanvasSize + UDim2.new(0, 0, 0, 25)
                    NEW('TextLabel', LOGS_TAB.Logs, {
                        BackgroundTransparency = 1,
                        Font = 'Code',
                        Position = UDim2.new(0, 0, 0, LOGS_Y),
                        Size = UDim2.new(1, 0, 0, 25),
                        Text = ' ' .. LOG .. '"',
                        TextColor3 = Color3.fromRGB(255, 255, 255),
                        TextSize = 15,
                        TextXAlignment = 'Left'
                    })
                    LOGS_Y = LOGS_Y + 25
                    LOGS_TAB.Logs.CanvasPosition = Vector2.new(0, LOGS_Y)
                end
            end
        end
        
        function END_AT(S, V)
            local F = S:find(V)
            if F then
                return S:sub(0, F - #V), true
            end
            return S, false
        end
        
        function FIND_COMMAND(C)
            for i,v in pairs(COMMANDS) do
                if v.CMD:lower() == C:lower() or TABLE(v.ALIAS, C:lower()) then
                    return v
                end
            end
        end
        
        function GET_ARGS(S)
            local A = {}
            repeat
                local NA, HS = END_AT(S:lower(), ' ')
                if NA ~= '' then
                    table.insert(A, NA)
                    S = S:sub(#NA + 2)
                end
            until not HS
            return A
        end
        
        function GET_COMMAND(S)
            local CMD, HS = END_AT(S:lower(), ' ')
            if HS then
                return {CMD, true}
            end
            return {CMD, false}
        end
        
        function GET_PLAYER(S, SP)
            local PT = {}
            if S:lower() == 'me' then
                table.insert(PT, SP)
            elseif S:lower() == 'random' then
                table.insert(PT, _PLAYERS:GetPlayers()[math.random(#_PLAYERS:GetPlayers())])
            end
            for i,v in pairs(_PLAYERS:GetPlayers()) do
                if S:lower() == 'admins' then
                    if CHECK_ADMIN(v.UserId) then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'all' then
                    table.insert(PT, v)
                elseif S:lower() == 'bcs' then
                    if v.MembershipType == Enum.MembershipType.BuildersClub then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'close' then
                    if v ~= SP and v.Character and SP.Character and (v.Character:GetModelCFrame().p - SP.Character:GetModelCFrame().p).magnitude <= 50 then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'far' then
                    if v ~= SP and v.Character and SP.Character and (v.Character:GetModelCFrame().p - SP.Character:GetModelCFrame().p).magnitude > 50 then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'friends' then
                    if v:IsFriendsWith(SP.UserId) then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'guests' then
                    if v.Guest then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'nbcs' then
                    if v.MembershipType == Enum.MembershipType.None then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'nonadmins' then
                    if not CHECK_ADMIN(v.UserId) then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'nonfriends' then
                    if not v:IsFriendsWith(SP.UserId) then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'nonguests' then
                    if not v.Guest then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'obcs' then
                    if v.MembershipType == Enum.MembershipType.OutrageousBuildersClub then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'others' then
                    if v ~= SP then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'tbcs' then
                    if v.MembershipType == Enum.MembershipType.TurboBuildersClub then
                        table.insert(PT, v)
                    end
                elseif S:lower() == 'team' then
                    if v.TeamColor == SP.TeamColor then
                        table.insert(PT, v)
                    end
                else
                    if v.Name:lower():sub(1, #S) == S:lower() then
                        table.insert(PT, v)
                    end
                end
            end
            return PT
        end
        
        function GLS(A)
            local S = ''
            for i,v in pairs(ARGS) do
                if i >= A then
                    if S ~= '' then
                        S = S .. ' ' .. v
                    else
                        S = S .. v
                    end
                end
            end
            return S
        end
        
        function HANDLE_CHAT(P)
            P.Chatted:Connect(function(C)
                if C:sub(1, -#C) == PREFIX then
                    COMMAND(C:sub(2, #C), P)
                end
            end)
        end
        
        function TABLE(T, V)
            for i,v in pairs(T) do
                if v == V then
                    return true
                end
            end
            return false
        end
        
    -- | EXTRA FUNCTIONS | --
        function COLOR(CH, C, R)
            local function SCAN(I)
                for i,v in pairs(I:GetChildren()) do
                    if v:IsA('BasePart') then
                        v.Color = C
                        v.Reflectance = R
                    elseif v:IsA('Decal') or v:IsA('Pants') or v:IsA('Shirt') or v:IsA('ShirtGraphic') then
                        v:Destroy()
                    elseif v:IsA('SpecialMesh') then
                        v.TextureId = ''
                    end
                    SCAN(v)
                end
            end
            SCAN(CH)
        end
        
        function GET_BODY(I)
            local L = {}
            for i,v in pairs(I:GetChildren()) do
                if v:IsA('BasePart') and BODY[v.Name] then
                    table.insert(L, v)
                end
            end
            return L
        end
        
        function INFECT(P)
            for i,v in pairs(GET_BODY(P.Character)) do
                if v.Name:find('Arm') or v.Name == 'Head' then
                    v.BrickColor = BrickColor.new('Medium green')
                elseif v.Name:find('Leg') or v.Name:find('Torso') then
                    v.BrickColor = BrickColor.new('Reddish brown')
                end
            end
            if FFCOC(P.Character, 'Humanoid') then
                FFCOC(P.Character, 'Humanoid').Touched:Connect(function(T)
                    if _PLAYERS:GetPlayerFromCharacter(T.Parent) and not T.Parent:FindFirstChild('Aperture_Infect') then
                        INFECT(_PLAYERS:GetPlayerFromCharacter(T.Parent))
                    end
                end)
            end
            Instance.new('Folder', P.Character).Name = 'Aperture_Infect'
        end
        
    -- | COMMANDS | --
        ADD_COMMAND('admin', 'admin [plr]', {}, function(A, SP)
            for i,v in pairs(GET_PLAYER(A[1], SP)) do
