                    table.insert(ADMINS, v.UserId)
                end
            end
        end)
        
        ADD_COMMAND('age', 'age [plr]', {}, function(A, SP)
            for i,v in pairs(GET_PLAYER(A[1], SP)) do
                local Y = math.floor(v.AccountAge / 365)
                local D = v.AccountAge - (Y * 365)
                if Y == 1 then Y = Y .. ' year' else Y = Y .. ' years' end
                if D == 1 then D = D .. ' day' else D = D .. ' days' end
                NOTIFY(v.Name, Y .. ' ' .. D)
            end
        end)
        
        ADD_COMMAND('ambient', 'ambient [r] [g] [b]', {}, function(A, SP)
            if tonumber(A[1]) and tonumber(A[2]) and tonumber(A[3]) then
