            end
        end)
        --Skidded af
        ADD_COMMAND('asteroid', 'asteroid [plr]', {}, function(A, SP)
            for i,v in pairs(GET_PLAYER(A[1], SP)) do
                if v.Character:FindFirstChild('HumanoidRootPart') then
                    local A = NEW('Part', workspace, {Position = v.Character.HumanoidRootPart.Position + Vector3.new(0, 500, 0), Size = Vector3.new(12, 12, 12)})
                    local BS = NEW('Sound', A, {Volume = 1, SoundId = 'rbxassetid://188590169'})
                    local F = NEW('Fire', A, {Heat = 25, Size = 30})
                    local FS = NEW('Sound', A, {Looped = true, Volume = 1, SoundId = 'rbxassetid://179438534'})
                    local S = NEW('Smoke', A, {RiseVelocity = 10, Size = 10})
                    NEW('SpecialMesh', A, {MeshId = 'rbxassetid://1290033', Scale = Vector3.new(6.2, 6.2, 6.2), TextureId = 'rbxassetid://1290030'})
                    FS:Play()
                    local TO = false
                    task.spawn(function()
                        repeat wait()
                            A.Position = Vector3.new(v.Character.HumanoidRootPart.Position.X, A.Position.Y, v.Character.HumanoidRootPart.Position.Z)
                        until not A or TO
                    end)
                    A.Touched:Connect(function(T)
                        if not TO then
                            TO = true
                            T:BreakJoints()
                            NEW('Explosion', A, {
                                BlastPressure = 1e6,
                                BlastRadius = 30,
                                Position = A.Position
                            })
                            F.Heat = 0
                            S.RiseVelocity = 0
                            FS:Stop()
                            BS:Play()
                            task.spawn(function()
                                wait(5)
                                BS:Stop()
                                if A then
                                    A:Destroy()
                                end
                            end)
                        end
                    end)
                end
            end
        end)
        
