            for i,v in pairs(GET_PLAYER(A[1], SP)) do
                if tonumber(A[2]) and FFCOC(v.Character, 'Humanoid') then
                    for i,v in pairs(v.Character:GetChildren()) do
                        if v:IsA('CharacterMesh') then
                            v:Destroy()
                        end
                    end
                    local T = game:FindService('AssetService'):GetAssetIdsForPackage(A[2])
                    if #T > 0 then
                        for _,a in pairs(T) do
                            local P = game:GetObjects('rbxassetid://' .. a)
                            for _,b in pairs(P) do
                                if b:IsA('Accoutrement') or b:IsA('CharacterMesh') then
                                    b.Parent = v.Character
                                elseif b:IsA('Folder') then
                                    if FFCOC(v.Character, 'Humanoid').RigType == Enum.HumanoidRigType.R6 and b.Name == 'R6' then
                                        b:GetChildren()[1].Parent = v.Character
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end)
        
