            end
        end)
        
        GUI['Command Bar'].FocusLost:Connect(function()
            COMMAND(GUI['Command Bar'].Text, LP)
            GUI['Command Bar'].Text = 'COMMAND INPUT'
        end)
        
        -- | COMMAND LIST
        function LIST(T)
            -- | Clear
            for i,v in pairs(GUI.Commands.List:GetChildren()) do
                v:Destroy()
            end
            GUI.Commands.List.CanvasSize = UDim2.new(0, 0, 0, 0)
            -- | List
            local Y = 3
            for i,v in pairs(T) do
                GUI.Commands.List.CanvasSize = GUI.Commands.List.CanvasSize + UDim2.new(0, 0, 0, 28)
                NEW('TextLabel', GUI.Commands.List, {
                    BackgroundColor3 = Color3.fromRGB(44, 44, 44),
                    BorderSizePixel = 0,
                    Font = 'Code',
                    Name = v.CMD,
                    Position = UDim2.new(0, 3, 0, Y),
                    Size = UDim2.new(1, -9, 0, 25),
                    Text = ' ' .. v.USAGE,
                    TextColor3 = Color3.fromRGB(255, 255, 255),
                    TextSize = 15,
                    TextXAlignment = 'Left'
                })
                Y = Y + 28
            end
            GUI.Commands.List.CanvasSize = GUI.Commands.List.CanvasSize + UDim2.new(0, 0, 0, 3)
        end
        LIST(COMMANDS)
        
        GUI.Commands.Close.MouseButton1Down:Connect(function()
            GUI.Commands.Visible = false
        end)
        
        GUI.Commands.Search:GetPropertyChangedSignal('Text'):Connect(function()
            local T = {}
            if GUI.Commands.Search.Text:find('^%s*$') then
                LIST(COMMANDS)
            end
            repeat
                if GUI.Commands.Search.Text:find(' ') then
                    GUI.Commands.Search.Text = GUI.Commands.Search.Text:gsub(' ', '')
                end
            until not GUI.Commands.Search.Text:find(' ')
            for i,v in pairs(COMMANDS) do
                --[[if v.CMD:sub(1, #GUI.Commands.Search.Text) == GUI.Commands.Search.Text:lower() then
                    table.insert(T, v)
                end]]
                if v.CMD:find(GUI.Commands.Search.Text:lower()) then
                    table.insert(T, v)
                end
            end
            LIST(T)
        end)
        
        GUI.Commands.Search.FocusLost:Connect(function()
            if GUI.Commands.Search.Text:find('^%s*$') then
                GUI.Commands.Search.Text = 'SEARCH'
                LIST(COMMANDS)
            end
        end)
        
        -- | HELP
        EXTRA_TAB.Info.Scroll.CanvasSize = EXTRA_TAB.Info.Scroll.CanvasSize + UDim2.new(0, 0, 0, 25)
        for i,v in pairs(HELP) do
            EXTRA_TAB.Info.Scroll.CanvasSize = EXTRA_TAB.Info.Scroll.CanvasSize + UDim2.new(0, 0, 0, 20)
            local A = NEW('TextLabel', EXTRA_TAB.Info.Scroll, {BackgroundTransparency = 1, Font = 'Code', Position = UDim2.new(0, 0, 0, HELP_Y), Size = UDim2.new(0.3, -20, 0, 20), Text = v['A'], TextColor3 = Color3.fromRGB(255, 255, 255), TextSize = 18, TextXAlignment = 'Right'})
            local V = NEW('TextLabel', A, {BackgroundTransparency = 1, Font = 'Code', Position = UDim2.new(1, 0, 0, 0), Size = UDim2.new(0, 40, 0, 20), Text = '|', TextColor3 = Color3.fromRGB(255, 255, 255), TextSize = 18})
            local T = NEW('TextLabel', A, {BackgroundTransparency = 1, Font = 'Code', Position = UDim2.new(1, 40, 0, 0), Size = UDim2.new(0.7, 0, 0, 20), Text = v['T'], TextColor3 = Color3.fromRGB(255, 255, 255), TextSize = 18, TextXAlignment = 'Left'})
            HELP_Y = HELP_Y + 20
        end
        EXTRA_TAB.Info.Scroll.CanvasSize = EXTRA_TAB.Info.Scroll.CanvasSize + UDim2.new(0, 0, 0, 5)
        
