 function SpawnBullet(CFpos,BForce,DForce,waight)
coroutine.resume(coroutine.create(function()
	local Bscale = 2
	local dahspeed=0
if attack == true and mememode == true then
	dahspeed=3
end --/dahspeed
	
	

	
	
local Stone=Instance.new("Part",Effects)	
		Stone.Reflectance = 0
