local animejumpscaresadrc7h = createScriptButton("anime", function(btn)
	btn.Text = "Loading... Please Wait"
	task.wait(0.5)
	btn.Text = "anime"
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")

local function ProCoughShake(guiObject, duration, intensity)
	local originalPos = guiObject.Position
	local startTime = tick()
	local connection
	connection = RunService.Heartbeat:Connect(function()
		local t = tick() - startTime
		if t >= duration then
			guiObject.Position = originalPos
			connection:Disconnect()
			return
		end
		local shakeX = math.random(-intensity, intensity)
		local shakeY = math.random(-intensity, intensity)
		local sway = math.sin(t * 25) * (intensity * 0.8)
		guiObject.Position = originalPos + UDim2.new(0, shakeX + sway, 0, shakeY)
	end)
end

local function ZoomRotate(guiObject, zoomScale, time)
	local tween = TweenService:Create(
		guiObject,
		TweenInfo.new(time, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		{
			Size = UDim2.new(
				guiObject.Size.X.Scale * zoomScale,
				guiObject.Size.X.Offset * zoomScale,
				guiObject.Size.Y.Scale * zoomScale,
				guiObject.Size.Y.Offset * zoomScale
			),
			Rotation = math.random(-5,5)
		}
	)
	tween:Play()
end

local function Jumpscare(v)
	if v:FindFirstChild("PlayerGui") and not v.PlayerGui:FindFirstChild("Screamer") then
		task.spawn(function()
			local newgui = Instance.new("ScreenGui")
			newgui.Name = "Screamer"
			newgui.IgnoreGuiInset = true
			newgui.ResetOnSpawn = false
			newgui.DisplayOrder = 10000
			newgui.Parent = v.PlayerGui
			local frame = Instance.new("Frame")
			frame.Parent = newgui
			frame.BackgroundColor3 = Color3.fromRGB(255,255,255)
			frame.Size = UDim2.new(1, 0, 1, 0)
			local newimage = Instance.new("ImageLabel")
			newimage.Parent = newgui
			newimage.Size = UDim2.new(0.95, 0, 0.93, 0)
			newimage.Position = UDim2.new(0.025, 0, 0.035, 0)
			newimage.BackgroundTransparency = 0
			newimage.BorderSizePixel = 0
			newimage.ScaleType = Enum.ScaleType.Stretch
			newimage.Image = "rbxassetid://119158248244319"
			local sou = Instance.new("Sound")
			sou.SoundId = "rbxassetid://82719020266339"
			sou.Volume = 10
			sou.Looped = false
			sou.Parent = newgui
			sou:Play()
			ProCoughShake(newimage, 0.6, 2)
			ZoomRotate(newimage, 1.02, 0.3)
			wait(2.342)
			ProCoughShake(newimage, 0.9, 6)
			ZoomRotate(newimage, 1.05, 0.25)
			newimage.Image = "rbxassetid://4344982548"
			ProCoughShake(newimage, 0.8, 5)
			ZoomRotate(newimage, 1.08, 0.25)
			sou.Ended:Connect(function() 
				newgui:Destroy()
			end)
		end)
	end
end

