    toggleDefense()
    updateButtons()
end)
stormButton = newButton("Grand Storm",function()
    toggleStorm()
    updateButtons()
end)
clickButton=newButton("Mouse Thunder Beam",function()
    clickThunder = not clickThunder
    updateButtons()
end)
