			local scale = math.random() * (MAX_DUCK_SCALE - MIN_DUCK_SCALE) + MIN_DUCK_SCALE

			local duck = Instance.new("Part")
			duck.Parent = workspace
			duck.Name = "duckyduckerduck"
			duck.Size = Vector3.new(scale, scale, scale)
			duck.Anchored = false
			duck.CanCollide = true

			duck.CFrame = CFrame.new(
				math.random(-1000, 1000),
				math.random(300, 700),
				math.random(-1000, 1000)
			)

			local mesh = Instance.new("FileMesh", duck)
			mesh.MeshId = "rbxassetid://521754610"
			mesh.TextureId = "rbxassetid://521754612"
			mesh.Scale = Vector3.new(scale, scale, scale)

			local quack = Instance.new("Sound", duck)
			quack.SoundId = "rbxassetid://198462271"
			quack.Volume = math.clamp(scale / 10, 1, 5)
			quack:Play()
			game.Debris:AddItem(quack, 0.5)
		end
	end)

	-- Cleanup
	task.spawn(function()
		while true do
			task.wait(20)
			for _, v in ipairs(workspace:GetChildren()) do
				if v.Name == "duckyduckerduck" then
					v:Destroy()
				end
			end
		end
	end)
end)

