-- c00lkidd
local c00lkidd = Instance.new("TextButton", Classics)
c00lkidd.TextWrapped = true
c00lkidd.BorderSizePixel = 0
c00lkidd.TextSize = 20
c00lkidd.TextColor3 = Color3.fromRGB(255, 255, 255)
c00lkidd.BackgroundColor3 = Color3.fromRGB(57, 57, 57)
c00lkidd.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json", Enum.FontWeight.Regular, Enum.FontStyle.Normal)
c00lkidd.Size = UDim2.new(0, 104, 0, 28)
c00lkidd.BorderColor3 = Color3.fromRGB(0, 0, 0)
c00lkidd.Text = "c00lkidd"
c00lkidd.Name = "c00lkidd"
c00lkidd.Position = UDim2.new(0.19549, 0, 0.5641, 0)

-- Flag to prevent duplicates
local chaosActivated = false

c00lkidd.MouseButton1Click:Connect(function()
    if chaosActivated then return end
    chaosActivated = true

    -- Sky setup
    if not game.Lighting:FindFirstChild("SKY") then
        local s = Instance.new("Sky")
        s.Name = "SKY"
        local skyID = "158118263"
        s.SkyboxBk = "rbxassetid://"..skyID
        s.SkyboxDn = "rbxassetid://"..skyID
        s.SkyboxFt = "rbxassetid://"..skyID
        s.SkyboxLf = "rbxassetid://"..skyID
        s.SkyboxRt = "rbxassetid://"..skyID
        s.SkyboxUp = "rbxassetid://"..skyID
        s.Parent = game.Lighting
    end

    -- Spooky sound
    if not game.Workspace:FindFirstChild("Spooky") then
        local Spooky = Instance.new("Sound", game.Workspace)
        Spooky.Name = "Spooky"
        Spooky.SoundId = "rbxassetid://72089843969979"
        Spooky.Volume = 5
        Spooky.Looped = true
        Spooky.Pitch = 0.2
        Spooky:Play()
    end

    local decalID = 158118263

    -- Apply decal
    local function applyDecal(part)
        if part:FindFirstChild("MYDECALHUE") then return end
        for i = 0, 5 do
            local D = Instance.new("Decal")
            D.Name = "MYDECALHUE"
            D.Face = i
            D.Texture = "rbxassetid://"..decalID
            D.Parent = part
        end
    end

    -- Apply particles
    local function applyParticles(part)
        if part:FindFirstChild("MYPARTICLES") then return end
        local particle = Instance.new("ParticleEmitter")
        particle.Name = "MYPARTICLES"
        particle.Texture = "rbxassetid://"..decalID
        particle.Rate = 20
        particle.Lifetime = NumberRange.new(1, 3)
        particle.Speed = NumberRange.new(1, 5)
        particle.Size = NumberSequence.new(1)
        particle.Parent = part
    end

    -- Chaos function
    local function chaosEverything(obj)
        if obj:IsA("BasePart") or obj:IsA("MeshPart") or obj:IsA("UnionOperation") then
            applyDecal(obj)
            applyParticles(obj)
        elseif obj:IsA("Model") then
            for _, child in pairs(obj:GetChildren()) do
                chaosEverything(child)
            end
        end
    end

    -- Apply to existing Workspace
    for _, v in pairs(game.Workspace:GetDescendants()) do
        chaosEverything(v)
    end

    -- Watch for new objects
    if not game.Workspace:FindFirstChild("ChaosListener") then
        local listenerFlag = Instance.new("Folder")
        listenerFlag.Name = "ChaosListener"
        listenerFlag.Parent = game.Workspace

if Connections.ChaosAdded then
    Connections.ChaosAdded:Disconnect()
end
if Connections.ChaosRemoving then
    Connections.ChaosRemoving:Disconnect()
end

Connections.ChaosAdded = game.Workspace.DescendantAdded:Connect(function(v)
    chaosEverything(v)
end)

Connections.ChaosRemoving = game.Workspace.DescendantRemoving:Connect(function(v)
    task.wait(0.1)
    if v.Parent then
        chaosEverything(v)
    end
end)
    end
end)


