Inferno.MouseButton1Click:Connect(function()
    -- Prevent duplicates
    if game.Workspace:FindFirstChild("InfernoActive") then return end
    local flag = Instance.new("Folder")
    flag.Name = "InfernoActive"
    flag.Parent = game.Workspace

    -- Change Lighting
    game.Lighting.Ambient = Color3.fromRGB(255, 50, 0)
    game.Lighting.OutdoorAmbient = Color3.fromRGB(255, 100, 0)
    game.Lighting.FogColor = Color3.fromRGB(255, 60, 0)
    game.Lighting.FogEnd = 300
    game.Lighting.FogStart = 0

    -- Add flames to all parts
    local function applyInferno(part)
        if part:IsA("BasePart") then
            -- Fire effect
            if not part:FindFirstChild("InfernoFire") then
                local fire = Instance.new("Fire")
                fire.Name = "InfernoFire"
                fire.Heat = 1000
                fire.Size = 500
                fire.Color = Color3.fromRGB(255, 80, 0)
                fire.SecondaryColor = Color3.fromRGB(255, 140, 0)
                fire.Parent = part
            end
        end
    end

    -- Apply to all existing Workspace objects
    for _, v in pairs(game.Workspace:GetDescendants()) do
        if v:IsA("BasePart") or v:IsA("MeshPart") or v:IsA("UnionOperation") then
            applyInferno(v)
        end
    end

    -- Auto-apply to new parts
if Connections.InfernoAdded then
    Connections.InfernoAdded:Disconnect()
end

Connections.InfernoAdded = game.Workspace.DescendantAdded:Connect(function(v)
    if v:IsA("BasePart") or v:IsA("MeshPart") or v:IsA("UnionOperation") then
        applyInferno(v)
    end
end)

    -- Add hellish soundscape
    if not game.Workspace:FindFirstChild("InfernoSound") then
        local s = Instance.new("Sound", game.Workspace)
        s.Name = "InfernoSound"
        s.SoundId = "rbxassetid://2787093357" -- fire/hell ambient
        s.Looped = true
        s.Volume = 10
        s:Play()
    end
end)

