    title.BackgroundTransparency = 1
    title.Font = Enum.Font.SourceSansBold
    title.TextColor3 = Color3.fromRGB(245, 245, 245)
    title.Parent = holder
   
    local shadow = title:Clone()
    shadow.ZIndex = 1
    shadow.AnchorPoint = title.AnchorPoint
    shadow.TextColor3 = Color3.fromRGB(0, 0, 0)
    shadow.TextTransparency = 0.9
    shadow.Position = title.Position + UDim2.fromOffset(1, 1)
    shadow.ZIndex = title.ZIndex - 1
    shadow.Parent = holder

    -- DESC
    local desc = Instance.new("TextLabel")
    desc.Text = "from " .. plr.Name
    desc.Size = UDim2.new(0, 300, 0, 25)
    desc.AnchorPoint = Vector2.new(0.5, 0.5)
