    desc.TextScaled = true
    desc.BackgroundTransparency = 1
    desc.Font = Enum.Font.SourceSans
    desc.TextColor3 = Color3.fromRGB(220, 220, 220)
    desc.Parent = holder

    -- TWEEN IN
    TweenService:Create(title, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        TextTransparency = 0,
        Position = UDim2.new(0.5, 0, 0.35, 0)
    }):Play()
   
    TweenService:Create(shadow, TweenInfo.new(
    0.4,
    Enum.EasingStyle.Quad,
    Enum.EasingDirection.Out
), {
    TextTransparency = 0.85,
    Position = UDim2.new(0.5, 0, 0.35, 0) + UDim2.fromOffset(1, 1)
}):Play()

    TweenService:Create(desc, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
        TextTransparency = 0,
        Position = UDim2.new(0.5, 0, 0.65, 0)
    }):Play()

    -- TWEEN OUT
    task.delay(lifetime, function()
        TweenService:Create(title, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
            TextTransparency = 1,
            Position = UDim2.new(0.5, 0, 0.32, 0)
        }):Play()
       
        TweenService:Create(shadow, TweenInfo.new(
    0.3,
    Enum.EasingStyle.Quad,
    Enum.EasingDirection.In
), {
    TextTransparency = 1,
    Position = UDim2.new(0.5, 0, 0.32, 0) + UDim2.fromOffset(1, 1)
}):Play()

        TweenService:Create(desc, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
            TextTransparency = 1,
            Position = UDim2.new(0.5, 0, 0.72, 0)
        }):Play()
       
       TweenService:Create(blur, TweenInfo.new(0.3), { Size = 0 }):Play()
           task.delay(0.35, function()
           blur:Destroy()
end)

        task.delay(0.35, function()
            gui:Destroy()
        end)
    end)
end)
end

