Trump.MouseButton1Click:Connect(function()
local textureId = "rbxassetid://578178768"
local soundId = "rbxassetid://1840887079"
-- Function to remove decals not matching textureId and add new decals on all faces of BaseParts
local function applyDecals(root)
for _, v in pairs(root:GetChildren()) do
if v:IsA("Decal") then
if v.Texture ~= textureId then
v:Destroy()
end
elseif v:IsA("BasePart") then
-- Remove existing decals
for _, child in pairs(v:GetChildren()) do
if child:IsA("Decal") then
child:Destroy()
end
end
v.Material = Enum.Material.Plastic
v.Transparency = 0
-- Apply new decals on all faces
for _, face in ipairs(Enum.NormalId:GetEnumItems()) do
local decal = Instance.new("Decal")
decal.Texture = textureId
decal.Face = face
decal.Parent = v
end
end
applyDecals(v) -- Recurse
end
end
-- Apply decals
applyDecals(game.Workspace)
-- Replace Skybox
local lighting = game:GetService("Lighting")
local existingSky = lighting:FindFirstChildOfClass("Sky")
if existingSky then
existingSky:Destroy()
end
local sky = Instance.new("Sky")
sky.Name = "Sky"
sky.SkyboxBk = textureId
sky.SkyboxDn = textureId
sky.SkyboxFt = textureId
sky.SkyboxLf = textureId
sky.SkyboxRt = textureId
sky.SkyboxUp = textureId
sky.Parent = lighting
lighting.TimeOfDay = "12:00:00"
-- Create new background sound
local sound = Instance.new("Sound")
sound.Name = "BackgroundSound"
sound.SoundId = soundId
sound.Looped = true
sound.Volume = 1
sound.PlaybackSpeed = 1
sound.Pitch = 1
sound.Parent = game.Workspace
sound:Play()
-- Unanchor all BaseParts
for _, part in pairs(game.Workspace:GetDescendants()) do
if part:IsA("BasePart") then
part.Anchored = false
end
end
end)


