Unanchor.Name = "Unanchor";
Unanchor.Position = UDim2.new(0.03333, 0, 0.4188, 0);
Unanchor.MouseButton1Click:Connect(function()
    local function unanchor(obj)
        if obj:IsA("BasePart") or obj:IsA("MeshPart") or obj:IsA("UnionOperation") or obj:IsA("TrussPart") then
            obj.Anchored = false
        end

        for _, cons in pairs(obj:GetDescendants()) do
            if cons:IsA("Constraint") then
                pcall(function() cons.Enabled = false end)
            end
        end
    end

    for _, obj in pairs(game.Workspace:GetDescendants()) do
        unanchor(obj)
    end

if Connections.Unanchor then
    Connections.Unanchor:Disconnect()
end

Connections.Unanchor = game.Workspace.DescendantAdded:Connect(function(obj)
    unanchor(obj)
end)
end)

