env.decompile = decompile or (function()
    if not env.getscriptbytecode then return end

    local API = "http://api.plusgiant5.com"
    local last_call = 0
    local request = env.request

    -- HTTP call helper
    local function call(konstantType, scriptPath)
        local success, bytecode = pcall(getscriptbytecode, scriptPath)
        if not success then
            return "-- Failed to get script bytecode:\n-- " .. tostring(bytecode)
        end

        local elapsed = os.clock() - last_call
        if elapsed < 0.5 then
            task.wait(0.5 - elapsed)
        end

        local httpResult = request({
            Url = API .. konstantType,
            Body = bytecode,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "text/plain"
            }
        })

        last_call = os.clock()

        if httpResult.StatusCode ~= 200 then
            return "-- Konstant API error:\n-- " .. tostring(httpResult.Body)
        end

        return httpResult.Body
    end

    local cache = {}

    local function decompileCached(scr)
        local key = scr:GetDebugId()

        if cache[key] then
            return cache[key]
        end

        local result = call("/konstant/decompile", scr)
        cache[key] = result
        return result
    end

    -- Public decompile function
    local function decompile(scriptPath)
        return decompileCached(scriptPath)
    end

    getgenv().decompile = decompile
    env.decompile = decompile
    return decompile
end)()

		if identifyexecutor then
			Main.Executor = identifyexecutor()
		end

